INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('100-all-time-favorites-usa-enfres', 'NDS', '100 All-Time Favorites (USA) (En,Fr,Es)', '2009', 'Compilation', 'Various', '1-4', 'Classic', 'A collection of various casual card, board, and arcade games.', 'Complete various levels and beat high scores.', 'A massive collection of classic casual games.', 'Never get bored with 100 All-Time Favorites on NDS. Featuring a huge variety of classics like Solitaire, Chess, and Sudoku, this collection is the ultimate companion for casual gaming on the go.');
