INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1000-bornes---coups-fourres-et-courses-folles!-france', 'NDS', '1000 Bornes - Coups-Fourres et Courses Folles! (France)', '2009', 'Board Game', 'DTP Entertainment', '1-4', 'Party', 'Digital card game based on the traditional French card game.', 'Be the first player to reach 1000 miles in a race.', 'A faithful adaptation of the classic card game.', '1000 Bornes brings the beloved French racing card game to the NDS. Strategize your way through hazards and speed limits to reach the finish line first in this addictive digital board game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1000-cooking-recipes-from-elle-a-table-europe-enfrdeesit-ndsi-enhanced', 'NDS', '1000 Cooking Recipes from Elle a Table (Europe) (En,Fr,De,Es,It) (NDSi Enhanced)', '2009', 'Cooking', 'Game Factory', '1', 'Educational', 'Interactive digital cookbook with voice control and search features.', 'Follow recipes to create gourmet dishes from Elle Magazine.', 'A premium digital interactive cookbook.', 'Elevate your kitchen skills with 1000 Cooking Recipes from Elle a Table. Utilizing NDSi features, this interactive guide offers professional culinary advice and easy-to-follow steps for world-class dining.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('101-dino-pets-europe-enfrdeit', 'NDS', '101 Dino Pets (Europe) (En,Fr,De,It)', '2010', 'Simulation', 'Tivola', '1', 'Casual', 'Virtual pet simulation with feeding, bathing, and play mechanics.', 'Raise and care for your very own pet dinosaur.', 'A dinosaur-themed virtual pet simulator.', '101 Dino Pets lets you adopt a prehistoric friend. Care for your dinosaur from an egg to adulthood by playing games and keeping them happy in this charming virtual pet experience for NDS.');
