INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('12-family-games-europe', 'NDS', '12 Family Games (Europe)', '2009', 'Family', 'Enjoy Gaming', '1-4', 'Party', 'A compilation of board and parlor games for the family.', 'Win matches in various classic board game favorites.', 'A digital collection of 12 classic family games.', '12 Family Games is the perfect NDS title for group fun. Featuring favorites like Ludo and Snakes & Ladders, it provides a convenient way to play traditional board games anywhere with friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('123-sesame-street---cookies-counting-carnival---the-videogame-australia', 'NDS', '123 Sesame Street - Cookie''s Counting Carnival - The Videogame (Australia)', '2010', 'Educational', 'Black Lantern Studios', '1', 'Educational', 'Educational mini-games focusing on counting and numbers.', 'Help Cookie Monster collect cookies while learning math.', 'A math-focused educational game for kids.', 'Join Cookie Monster in Cookie''s Counting Carnival. This NDS title makes learning numbers fun for young children through engaging Sesame Street mini-games and intuitive touch controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('123-sesame-street---elmos-a-to-zoo-adventure---the-videogame-australia', 'NDS', '123 Sesame Street - Elmo''s A-to-Zoo Adventure - The Videogame (Australia)', '2010', 'Educational', 'Black Lantern Studios', '1', 'Educational', 'Educational mini-games focusing on the alphabet and animals.', 'Help Elmo navigate the zoo while learning letters.', 'An alphabet-focused educational game for kids.', 'Elmo''s A-to-Zoo Adventure is a perfect early learning tool on NDS. Children can explore the zoo with Elmo while practicing their ABCs and discovering fascinating facts about animals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('123-sesame-street---elmos-musical-monsterpiece-usa-enes', 'NDS', '123 Sesame Street - Elmo''s Musical Monsterpiece (USA) (En,Es)', '2010', 'Educational', 'Black Lantern Studios', '1', 'Educational', 'Rhythm and music-based mini-games for young children.', 'Explore sounds and music with Elmo and friends.', 'A musical educational game for children.', 'Spark a love for music with Elmo''s Musical Monsterpiece. This Sesame Street title for NDS teaches kids about rhythm, instruments, and composition in a colorful and interactive environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('123-sesame-street---ready-set-grover!---with-elmo---the-videogame-usa-enes', 'NDS', '123 Sesame Street - Ready, Set, Grover! - With Elmo - The Videogame (USA) (En,Es)', '2011', 'Educational', 'Black Lantern Studios', '1', 'Educational', 'Physical activity and coordination mini-games for toddlers.', 'Complete various "get moving" challenges with Grover.', 'An active educational game for early learners.', 'Ready, Set, Grover! encourages young NDS players to stay active. Through fun, movement-based mini-games, kids learn about healthy habits and physical coordination alongside their favorite Muppets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1500-ds-spirits---mahjong-v-japan', 'NDS', '1500 DS Spirits - Mahjong V (Japan)', '2009', 'Mahjong', 'Tasuuke', '1-4', 'Traditional', 'Traditional Japanese Mahjong simulation using touch screen controls.', 'Defeat AI opponents and master Mahjong strategies.', 'A high-quality Mahjong sim for NDS.', 'Part of the popular budget series, 1500 DS Spirits - Mahjong V offers a refined Japanese Mahjong experience with challenging AI and intuitive dual-screen interface for board game enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1500-ds-spirits---shougi-v-japan', 'NDS', '1500 DS Spirits - Shougi V (Japan)', '2009', 'Board Game', 'Tasuuke', '1-2', 'Traditional', 'Strategic board gameplay based on traditional Japanese Chess.', 'Checkmate the opponent''s king using tactical moves.', 'Authentic Japanese Shougi simulation.', '1500 DS Spirits - Shougi V provides a deep and authentic Shougi experience. Test your strategic thinking against various difficulty levels in this portable version of Japan''s classic chess-like game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1500-ds-spirits-vol-1---mahjong-japan', 'NDS', '1500 DS Spirits Vol. 1 - Mahjong (Japan)', '2008', 'Mahjong', 'Tasuuke', '1-4', 'Traditional', 'Traditional Japanese Mahjong simulation using touch screen controls.', 'Defeat AI opponents and master Mahjong strategies.', 'A classic Mahjong digital adaptation.', '1500 DS Spirits Vol. 1 - Mahjong brings the essential tile-based strategy game to the NDS. Perfect for quick sessions, it features clean graphics and robust AI for Mahjong fans of all levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1500-ds-spirits-vol-10---igo-japan', 'NDS', '1500 DS Spirits Vol. 10 - Igo (Japan)', '2008', 'Board Game', 'Tasuuke', '1-2', 'Traditional', 'Classic Go (Igo) gameplay focusing on territorial control.', 'Capture more territory than the opponent on the board.', 'Traditional Go strategy game for NDS.', 'Master the ancient art of Go with 1500 DS Spirits Vol. 10 - Igo. This digital version provides a focused environment to practice your stones placement and tactical board control on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1500-ds-spirits-vol-2---shougi-japan', 'NDS', '1500 DS Spirits Vol. 2 - Shougi (Japan)', '2008', 'Board Game', 'Tasuuke', '1-2', 'Traditional', 'Strategic board gameplay based on traditional Japanese Chess.', 'Checkmate the opponent''s king using tactical moves.', 'A portable Shougi board game.', '1500 DS Spirits Vol. 2 - Shougi allows players to enjoy the complexity of Japanese Chess anywhere. Its simple interface and smart AI make it an ideal entry point for the "1500 DS Spirits" budget line.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1500-ds-spirits-vol-3---block-kuzushi-japan', 'NDS', '1500 DS Spirits Vol. 3 - Block Kuzushi (Japan)', '2008', 'Puzzle', 'Tasuuke', '1-2', 'Casual', 'Arcade-style brick breaking gameplay with a paddle and ball.', 'Clear all blocks on the screen to progress to the next level.', 'Classic block-breaking arcade action.', '1500 DS Spirits Vol. 3 - Block Kuzushi offers timeless arcade fun. Use the stylus to control your paddle, hit the ball, and destroy colorful block patterns in this addictive handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1500-ds-spirits-vol-4---reversi-japan', 'NDS', '1500 DS Spirits Vol. 4 - Reversi (Japan)', '2008', 'Board Game', 'Tasuuke', '1-2', 'Traditional', 'Board game gameplay where players flip opponent discs.', 'Have the majority of your color discs on the board at the end.', 'A digital version of the classic Reversi.', 'Strategy meets simplicity in 1500 DS Spirits Vol. 4 - Reversi. This NDS title challenges players to outsmart the AI in the classic game of ''flips'', where one move can change the entire board state.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1500-ds-spirits-vol-5---hanafuda-japan', 'NDS', '1500 DS Spirits Vol. 5 - Hanafuda (Japan)', '2008', 'Card Game', 'Tasuuke', '1-4', 'Traditional', 'Traditional Japanese card game using a flower-themed deck.', 'Collect sets of cards to earn points and win rounds.', 'Traditional Hanafuda card game sim.', 'Experience the beautiful tradition of Hanafuda with 1500 DS Spirits Vol. 5. Play classic games like Koi-Koi with high-quality card art and responsive touch controls tailored for the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1500-ds-spirits-vol-6---trump-japan', 'NDS', '1500 DS Spirits Vol. 6 - Trump (Japan)', '2008', 'Card Game', 'Tasuuke', '1-4', 'Traditional', 'Various Western card games played with a standard 52-card deck.', 'Win matches across multiple popular card game variants.', 'A collection of classic Western card games.', '1500 DS Spirits Vol. 6 - Trump features a variety of card staples like Poker and Blackjack. It’s an essential collection for anyone looking for quick and familiar card game action on their handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1500-ds-spirits-vol-7---chess-japan', 'NDS', '1500 DS Spirits Vol. 7 - Chess (Japan)', '2008', 'Board Game', 'Tasuuke', '1-2', 'Traditional', 'International Chess gameplay with standard rules and pieces.', 'Put the opponent''s king into checkmate.', 'A portable and challenging Chess sim.', '1500 DS Spirits Vol. 7 - Chess brings the world’s most famous strategy game to your NDS. With multiple AI difficulty settings, it''s perfect for both beginners learning the ropes and veteran grandmasters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1500-ds-spirits-vol-8---darts-japan', 'NDS', '1500 DS Spirits Vol. 8 - Darts (Japan)', '2008', 'Sports', 'Tasuuke', '1-4', 'Casual', 'Precision aiming and throwing mechanics using the stylus.', 'Score points by hitting specific targets on the board.', 'A realistic darts simulation for NDS.', 'Step up to the oche with 1500 DS Spirits Vol. 8 - Darts. Use the precision of the DS stylus to throw with accuracy in various game modes, including 301 and Cricket, in a realistic digital environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('1500-ds-spirits-vol-9---2-nin-uchi-mahjong-japan', 'NDS', '1500 DS Spirits Vol. 9 - 2-nin Uchi Mahjong (Japan)', '2008', 'Mahjong', 'Tasuuke', '1-2', 'Traditional', 'Fast-paced two-player variant of Japanese Mahjong.', 'Score more points than your single opponent in head-to-head play.', 'Focused 2-player Mahjong action.', '1500 DS Spirits Vol. 9 - 2-nin Uchi Mahjong streamlines the traditional game for faster, more intense head-to-head matches. Ideal for players who prefer a quicker pace and direct competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('18-card-games-europe-enfrdeesnl', 'NDS', '18 Card Games (Europe) (En,Fr,De,Es,Nl)', '2007', 'Card Game', 'Oxygen Games', '1-4', 'Classic', 'Selection of popular card games like Solitaire, Poker, and Hearts.', 'Master eighteen different card games and clear challenges.', 'A versatile pack of 18 card games.', '18 Card Games for NDS is a comprehensive digital deck. Whether you''re in the mood for a solo game of Solitaire or a competitive round of Poker, this European compilation has you covered.');
