INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('4-elements-europe-frde', 'NDS', '4 Elements (Europe) (Fr,De)', '2007', 'Puzzle', 'Frozenbyte', '1', 'Strategy Puzzle', 'Match-3 and hidden object gameplay with an elemental theme.', 'Restore the four elements to save a magical kingdom.', 'Fantasy-themed match-3 puzzle adventure.', '4 Elements combines engaging match-3 mechanics with a captivating fantasy story. Unlock powerful spells and restore the ancient altars in this visually stunning and addictive puzzle hybrid.');
