INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('4-game-pack!---clue-+-aggravation-+-perfection-+-mouse-trap-usa', 'NDS', '4 Game Pack! - Clue + Aggravation + Perfection + Mouse Trap (USA)', '2009', 'Board Game', 'EA Bright Light', '1-4', 'Party', 'Digital adaptations of four famous family and party games.', 'Solve mysteries and complete physical puzzle tasks.', '4-in-1 classic family game collection.', 'Featuring Clue, Aggravation, Perfection, and Mouse Trap, this pack brings together diverse gameplay styles ranging from mystery-solving to fast-paced physical puzzles in a single portable card.');
