INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('700-mannin-no-atama-o-yokusuru---chou-keisan-ds---13000-mon-+-image-keisan-japan', 'NDS', '700 Mannin no Atama o Yokusuru - Chou Keisan DS - 13000 Mon + Image Keisan (Japan)', '2009', 'Educational', 'IE Institute', '1', 'Brain Training', 'Fast-paced mathematical calculations and drills.', 'Complete 13,000 math problems to improve brain speed.', 'An intensive mental math training tool.', '700 Mannin no Atama o Yokusuru is the ultimate math trainer. Featuring over 13,000 problems, it uses repetitive calculation and image-based math to significantly boost your mental processing speed on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('7th-dragon-japan', 'NDS', '7th Dragon (Japan)', '2010', 'RPG', 'Imageepoch', '1', 'JRPG', 'Turn-based tactical RPG with party customization.', 'Hunt and defeat dragons to save the world of Eden.', 'A classic fantasy dungeon-crawling RPG.', '7th Dragon offers a deep JRPG experience where you lead a custom party of heroes. Navigate dangerous dungeons and engage in strategic turn-based combat to rid the land of the dragon menace.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('8ballallstars-europe-enfrdeesit', 'NDS', '8BallAllstars (Europe) (En,Fr,De,Es,It)', '2008', 'Sports', 'Playlogic', '1-4', 'Arcade', 'Stylus-controlled pool and billiards simulation.', 'Clear the table and win matches against AI or friends.', 'A stylish 8-ball pool simulation.', '8BallAllstars brings the pool hall to your handheld. With realistic physics and intuitive touch controls, you can pull off complex trick shots and compete in various tournament modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('99-no-namida-japan', 'NDS', '99 no Namida (Japan)', '2009', 'Adventure', 'Compile Heart', '1', 'Narrative', 'Narrative-driven visual novel with emotional themes.', 'Read through stories designed to move you to tears.', 'An emotional storytelling experience.', '99 no Namida (99 Tears) is a unique "emotional" software for NDS. It features a collection of short, poignant stories designed to evoke empathy and provide a cathartic reading experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('a-prendre-ou-a-laisser---le-jeu-officiel-france', 'NDS', 'A Prendre ou a Laisser - Le Jeu Officiel (France)', '2009', 'Game Show', 'Smileboom', '1-4', 'Party', 'Game show simulation based on the "Deal or No Deal" format.', 'Choose the right boxes to win the highest cash prize.', 'The official French Deal or No Deal game.', 'A Prendre ou a Laisser brings the tension of the TV show to your NDS. Make the right deals with the Banker and trust your intuition to walk away with the virtual jackpot in this official adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('a-ressha-de-ikou-ds-japan', 'NDS', 'A Ressha de Ikou DS (Japan)', '2009', 'Simulation', 'Artdink', '1', 'Train Simulation', 'Urban planning and railroad management simulation.', 'Build an efficient rail network and develop a city.', 'A deep railway-themed city builder.', 'A Ressha de Ikou DS (A-Train) allows you to become a transport tycoon. Manage train lines, schedules, and urban development in this detailed simulation that challenges your economic strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ab-durch-die-hecke-germany', 'NDS', 'Ab durch die Hecke (Germany)', '2006', 'Adventure', 'Edge of Reality', '1', 'Platformer', 'Stealth-based 3D action platformer.', 'Guide woodland creatures through suburban obstacles.', 'The official Over the Hedge movie game.', 'Ab durch die Hecke (Over the Hedge) follows RJ and Verne as they navigate human neighborhoods. Use stealth and teamwork to complete heists and avoid traps in this fun movie-based adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ace-attorney-investigations---miles-edgeworth-europe', 'NDS', 'Ace Attorney Investigations - Miles Edgeworth (Europe)', '2009', 'Adventure', 'Capcom', '1', 'Visual Novel', 'Point-and-click adventure and crime scene investigation.', 'Solve complex murders by finding contradictions in clues.', 'A legal investigation thriller starring Edgeworth.', 'Ace Attorney Investigations shifts the focus from the courtroom to the crime scene. Play as Miles Edgeworth, using logic and deduction to solve cases in this acclaimed spin-off series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ace-attorney-investigations---miles-edgeworth-usa', 'NDS', 'Ace Attorney Investigations - Miles Edgeworth (USA)', '2009', 'Adventure', 'Capcom', '1', 'Visual Novel', 'Point-and-click adventure and crime scene investigation.', 'Solve complex murders by finding contradictions in clues.', 'A legal investigation thriller starring Edgeworth.', 'Ace Attorney Investigations shifts the focus from the courtroom to the crime scene. Play as Miles Edgeworth, using logic and deduction to solve cases in this acclaimed spin-off series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ace-attorney-investigations:-miles-edgeworth-2-gyakuten-kenji-2-english-translated', 'NDS', 'Ace Attorney Investigations: Miles Edgeworth 2 (Gyakuten Kenji 2 English Translated)', '2011', 'Adventure', 'Capcom', '1', 'Visual Novel', 'Point-and-click adventure and crime scene investigation.', 'Uncover the truth behind a series of high-profile cases.', 'The fan-translated sequel to Miles Edgeworth.', 'Ace Attorney Investigations 2 (Gyakuten Kenji 2) continues the journey of Miles Edgeworth. Experience the most complex cases in the series with improved logic mechanics and a gripping, fan-translated narrative.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('actionloop-europe-enfrdeesit', 'NDS', 'Actionloop (Europe) (En,Fr,De,Es,It)', '2006', 'Puzzle', 'Enjoy Gaming', '1', 'Casual', 'Action-puzzle gameplay using magnetic marble physics.', 'Clear the screen by matching colored marbles in a loop.', 'A fast-paced magnetic marble puzzle game.', 'Actionloop (Magnetica) uses the NDS stylus to perfection. Launch marbles to create matches of three or more before they reach the center, in a frantic and addictive test of reflexes and planning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('active-health-with-carol-vorderman-europe', 'NDS', 'Active Health with Carol Vorderman (Europe)', '2008', 'Fitness', 'Lionhead Studios', '1', 'Health', 'Lifestyle and health tracking simulation.', 'Monitor your diet and exercise to improve well-being.', 'A digital health and fitness coach.', 'Active Health with Carol Vorderman helps you stay on track with your fitness goals. Use the NDS to log meals, track activity, and receive expert advice on maintaining a healthy lifestyle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('actua-pool-europe-endeesit', 'NDS', 'Actua Pool (Europe) (En,De,Es,It)', '2007', 'Sports', 'Actua Sports', '1-2', 'Simulation', 'Realistic 3D pool simulation with multiple game modes.', 'Master the art of billiards and win tournaments.', 'A professional pool and billiards game.', 'Actua Pool brings high-fidelity pool physics to the NDS. Compete in 8-ball, 9-ball, and various challenges with a 3D camera view that lets you line up every shot with professional precision.');
