INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('addy---do-you-speak-english-europe-frdeesit', 'NDS', 'Addy - Do You Speak English (Europe) (Fr,De,Es,It)', '2008', 'Educational', 'Clever Beans', '1', 'Language Learning', 'Educational language learning mini-games.', 'Learn English vocabulary and grammar through fun tasks.', 'An interactive English language tutor.', 'Addy - Do You Speak English is a specialized educational tool for kids. It uses interactive lessons and rewarding mini-games to make learning English as a second language engaging and effective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('addy-junior---mein-koerper-germany', 'NDS', 'Addy Junior - Mein Koerper (Germany)', '2008', 'Educational', 'Educa', '1', 'Educational', 'Interactive biology and health lessons for children.', 'Explore and learn about the functions of the human body.', 'An educational guide to the human body.', 'Addy Junior - Mein Koerper teaches young German-speaking children about anatomy and health. Through colorful illustrations and simple activities, kids discover how their organs and senses work.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adi-lentraineur---mathematiques-francais-6e-&-5e-france', 'NDS', 'Adi l''Entraineur - Mathematiques, Francais 6e & 5e (France)', '2008', 'Educational', 'Coktel Vision', '1', 'Educational', 'Curriculum-based math and French language exercises.', 'Master school subjects for 6th and 5th-grade levels.', 'An educational school support program.', 'Adi l''Entraineur provides comprehensive academic support for students. Covering the official French curriculum, it offers thousands of exercises to reinforce math and language skills on the go.');
