INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adi-lentraineur---objectif-anglais-france', 'NDS', 'Adi l''Entraineur - Objectif Anglais (France)', '2008', 'Educational', 'Coktel Vision', '1', 'Educational', 'Targeted English language learning and drills.', 'Improve English speaking and writing proficiency.', 'Specialized English training for students.', 'Adi l''Entraineur - Objectif Anglais focuses specifically on English language acquisition. It provides structured lessons and interactive tests to help French-speaking students master English fluency.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adibou---je-joue-a-lire-et-a-compter-france', 'NDS', 'Adibou - Je Joue a Lire et a Compter (France)', '2007', 'Educational', 'Coktel Vision', '1', 'Educational', 'Early childhood reading and counting activities.', 'Develop basic literacy and numeracy skills through play.', 'A preschool educational adventure.', 'Adibou - Je Joue a Lire et a Compter is designed for early learners. It combines fun characters with foundational lessons in reading and math to give young children a head start in their education.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adibou---je-joue-avec-les-lettres-et-les-nombres-france', 'NDS', 'Adibou - Je Joue avec les Lettres et les Nombres (France)', '2007', 'Educational', 'Coktel Vision', '1', 'Educational', 'Early childhood alphabet and number games.', 'Learn to recognize letters and numbers through interaction.', 'A foundational learning game for toddlers.', 'Adibou - Je Joue avec les Lettres et les Nombres makes early education fun. With friendly guidance, kids explore the world of symbols and digits through colorful and intuitive NDS touch-screen play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adibou-aventure---jexplore-le-corps-humain-france', 'NDS', 'Adibou Aventure - J''Explore le Corps Humain (France)', '2007', 'Educational', 'Coktel Vision', '1', 'Educational', 'Educational adventure exploring biological systems.', 'Discover how the human body works through a journey.', 'A kid-friendly human anatomy adventure.', 'Adibou Aventure takes children inside the human body. This educational NDS title turns biology into an exciting exploration, teaching kids about health and anatomy through interactive storytelling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-wars---dark-conflict-europe-enfrdeesit', 'NDS', 'Advance Wars - Dark Conflict (Europe) (En,Fr,De,Es,It)', '2008', 'Strategy', 'Intelligent Systems', '1-4', 'Turn-Based Strategy', 'Turn-based strategy with tactical grid movement and unit management.', 'Defeat enemy armies and survive a post-apocalyptic world.', 'Gritty turn-based military strategy game.', 'Experience a darker side of warfare in Advance Wars - Dark Conflict. This NDS strategy masterpiece features deep tactical combat, diverse military units, and a compelling story set in a world devastated by meteor strikes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-wars---days-of-ruin-usa-enfres', 'NDS', 'Advance Wars - Days of Ruin (USA) (En,Fr,Es)', '2008', 'Strategy', 'Intelligent Systems', '1-4', 'Turn-Based Strategy', 'Turn-based strategy with tactical grid movement and unit management.', 'Defeat enemy armies and survive a post-apocalyptic world.', 'Gritty turn-based military strategy game.', 'Advance Wars - Days of Ruin brings intense tactical gameplay to the NDS. Command your troops through challenging missions, utilize terrain advantages, and master the art of war in this acclaimed strategy sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-wars---dual-strike-europe-enfrdeesit', 'NDS', 'Advance Wars - Dual Strike (Europe) (En,Fr,De,Es,It)', '2005', 'Strategy', 'Intelligent Systems', '1-4', 'Turn-Based Strategy', 'Turn-based strategy using dual-screen combat and tag-team powers.', 'Defeat the Black Hole Army across various battlefronts.', 'Classic dual-screen tactical warfare.', 'Advance Wars - Dual Strike revolutionizes handheld strategy with its dual-screen battle system. Use powerful CO powers and tag-team tactics to outsmart your enemies in this definitive Nintendo DS strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-wars---dual-strike-usa', 'NDS', 'Advance Wars - Dual Strike (USA)', '2005', 'Strategy', 'Intelligent Systems', '1-4', 'Turn-Based Strategy', 'Turn-based strategy using dual-screen combat and tag-team powers.', 'Defeat the Black Hole Army across various battlefronts.', 'Classic dual-screen tactical warfare.', 'Advance Wars - Dual Strike revolutionizes handheld strategy with its dual-screen battle system. Use powerful CO powers and tag-team tactics to outsmart your enemies in this definitive Nintendo DS strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventure-time---hey-ice-king!-whyd-you-steal-our-garbage!!-usa', 'NDS', 'Adventure Time - Hey Ice King! Why''d You Steal Our Garbage!! (USA)', '2012', 'Adventure', 'WayForward', '1', 'Platformer', 'Side-scrolling action-adventure with RPG elements and exploration.', 'Journey through Ooo to find out why the Ice King stole your trash.', 'Whimsical Adventure Time action-RPG.', 'Join Finn and Jake in Adventure Time - Hey Ice King! Why''d You Steal Our Garbage!! This NDS adventure features classic platforming, funny dialogue, and a world filled with fan-favorite characters from the show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventures-of-pinocchio-europe', 'NDS', 'Adventures of Pinocchio (Europe)', '2008', 'Adventure', 'Creat Studios', '1', 'Storybook', 'Mini-game collection and story-based puzzles.', 'Follow Pinocchio''s journey and help him become a real boy.', 'An interactive storybook adventure for kids.', 'Adventures of Pinocchio on NDS brings the classic tale to life. Engage in child-friendly puzzles and mini-games that follow the narrative of the wooden puppet who dreams of becoming a human boy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('affari-tuoi-italy', 'NDS', 'Affari Tuoi (Italy)', '2008', 'Game Show', 'Spin-Off', '1-4', 'Party', 'Game show simulation based on picking mystery boxes.', 'Negotiate with the Banker to win the highest cash prize.', 'The official Italian "Deal or No Deal" game.', 'Affari Tuoi brings the excitement of the popular Italian TV show to your NDS. Test your luck and your nerves as you decide whether to keep your box or accept the Banker''s tempting offers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('afl-mascot-manor-australia', 'NDS', 'AFL Mascot Manor (Australia)', '2009', 'Adventure', 'Wicked Witch Software', '1', 'Platformer', 'Sports-themed mini-games and exploration with mascots.', 'Explore the Mascot Manor and win various sports challenges.', 'Fun Australian Rules Football mascot game.', 'AFL Mascot Manor is an engaging sports-adventure for younger fans. Play as your favorite AFL mascots, complete mini-games, and explore themed worlds in this unique Australian sports title for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('again---fbi-chou-shinri-sousakan-japan', 'NDS', 'Again - FBI Chou Shinri Sousakan (Japan)', '2010', 'Adventure', 'Tecmo', '1', 'Interactive Novel', 'Point-and-click mystery with dual-screen perspective mechanics.', 'Use past and present views to solve cold cases for the FBI.', 'An innovative interactive crime thriller.', 'Again - FBI Chou Shinri Sousakan (Interactive Crime Novel) uses a unique dual-screen view to compare crime scenes across time. Solve dark mysteries using the "Past Vision" ability in this atmospheric NDS thriller.');
