INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aibou-ds-japan', 'NDS', 'Aibou DS (Japan)', '2009', 'Adventure', 'Technos Japan', '1', 'Visual Novel', 'Visual novel mystery based on the popular Japanese TV drama.', 'Work with detectives Sugishita and Kameyama to solve crimes.', 'A crime-solving visual novel experience.', 'Aibou DS puts you inside the world of the hit Japanese police procedural. Interrogate suspects and analyze evidence to crack difficult cases alongside the famous duo in this engaging NDS mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('air-traffic-chaos-usa', 'NDS', 'Air Traffic Chaos (USA)', '2010', 'Simulation', 'Nintendo', '1', 'Management', 'Real-time air traffic control simulation using the stylus.', 'Safely manage takeoffs and landings at busy airports.', 'Intense air traffic control simulator.', 'Experience the pressure of a controller in Air Traffic Chaos. Manage multiple aircraft simultaneously, avoid collisions, and ensure on-time performance in this highly addictive and challenging NDS sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akachan-wa-doko-kara-kuru-no-japan', 'NDS', 'Akachan wa Doko kara Kuru no (Japan)', '2009', 'Educational', 'Spike', '1', 'Life Simulation', 'Quirky mini-game collection using all NDS input features.', 'Win the heart of a girl through bizarre and fun challenges.', 'Weird and wonderful Japanese mini-games.', 'Akachan wa Doko kara Kuru no (The Rub Rabbits!) is the stylish sequel to Feel the Magic. Use the touch screen and microphone to complete unique, romantic-themed challenges in a colorful pop-art world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akagawa-jirou-mystery---tsuki-no-hikari---shizumeru-kane-no-satsujin-japan', 'NDS', 'Akagawa Jirou Mystery - Tsuki no Hikari - Shizumeru Kane no Satsujin (Japan)', '2007', 'Adventure', 'Marvelous', '1', 'Mystery', 'Mystery adventure based on the novels of Jiro Akagawa.', 'Investigate a murder at a remote mansion to find the truth.', 'Classic Japanese murder mystery adventure.', 'Akagawa Jirou Mystery - Tsuki no Hikari brings high-stakes suspense to the NDS. Navigate a branching narrative and solve puzzles to uncover a killer in this atmospheric visual novel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akagawa-jirou-mystery---yasoukyoku---hon-ni-manekareta-satsujin-japan', 'NDS', 'Akagawa Jirou Mystery - Yasoukyoku - Hon ni Manekareta Satsujin (Japan)', '2008', 'Adventure', 'Marvelous', '1', 'Mystery', 'Mystery adventure based on the novels of Jiro Akagawa.', 'Solve a series of mysterious incidents involving a cursed book.', 'Supernatural murder mystery visual novel.', 'Akagawa Jirou Mystery - Yasoukyoku is a gripping detective game for NDS. Experience a suspenseful plot where literature and reality blur, requiring careful investigation and sharp deduction to solve.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akai-ito-destiny-ds-japan', 'NDS', 'Akai Ito Destiny DS (Japan)', '2008', 'Adventure', 'Success', '1', 'Romance Visual Novel', 'Visual novel with romantic and supernatural elements.', 'Navigate high school life and uncover the "red thread" of fate.', 'Supernatural romance visual novel.', 'Akai Ito Destiny DS is a heartwarming yet mysterious visual novel. Make choices that influence your relationships and discover the secrets behind the spiritual bonds connecting the main characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akai-ito-ds-japan', 'NDS', 'Akai Ito DS (Japan)', '2007', 'Adventure', 'Success', '1', 'Romance Visual Novel', 'Visual novel with romantic and supernatural elements.', 'Navigate high school life and uncover the "red thread" of fate.', 'Supernatural romance visual novel.', 'Akai Ito DS explores the legend of the red string of fate. This Japanese NDS title features beautiful art and multiple story paths where your decisions determine your romantic and spiritual destiny.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akko-de-pon!---ikasama-hourouki-japan', 'NDS', 'Akko de Pon! - Ikasama Hourouki (Japan)', '2009', 'Adventure', 'Compile Heart', '1', 'Visual Novel', 'Mahjong simulation with a twist and celebrity branding.', 'Win Mahjong matches against various quirky opponents.', 'Celebrity-themed Japanese Mahjong game.', 'Akko de Pon! offers a fun take on Mahjong for the NDS. Featuring Japanese TV personality Akiko Wada, it combines traditional tile gameplay with unique characters and a lighthearted atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akko-ni-omakase!---brain-shock-japan', 'NDS', 'Akko ni Omakase! - Brain Shock (Japan)', '2009', 'Puzzle', 'Compile Heart', '1', 'Brain Training', 'Brain training puzzles and cognitive challenges.', 'Improve your mental speed and logic through mini-games.', 'Brain training with a TV personality.', 'Akko ni Omakase! - Brain Shock provides a series of puzzles designed to stimulate your mind. Use the NDS touch screen to solve logic and memory tasks endorsed by the famous TV show "Akko ni Omakase!"');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akogare-girls-collection---lovely-youchien-nikki-japan', 'NDS', 'Akogare Girls Collection - Lovely Youchien Nikki (Japan)', '2009', 'Simulation', 'D3 Publisher', '1', 'Life Simulation', 'Career simulation focused on preschool education.', 'Take care of children and manage your daily life as a teacher.', 'Kindergarten teacher career simulator.', 'Lovely Youchien Nikki lets you experience the life of a kindergarten teacher. Care for toddlers, play educational games, and manage your school day in this charming career sim for the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akogare-girls-collection---suteki-ni-nurse-days-japan', 'NDS', 'Akogare Girls Collection - Suteki ni Nurse Days (Japan)', '2009', 'Simulation', 'D3 Publisher', '1', 'Life Simulation', 'Career simulation focused on nursing and healthcare.', 'Care for patients and learn the responsibilities of a nurse.', 'Medical nursing career simulator.', 'Suteki ni Nurse Days offers a glimpse into the medical world. Play through daily nursing routines, assist doctors, and care for patients in this detailed and educational career simulation for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akumajou-dracula---gallery-of-labyrinth-japan', 'NDS', 'Akumajou Dracula - Gallery of Labyrinth (Japan)', '2006', 'Action', 'Konami', '1', 'Metroidvania', '2D action-platformer with "Metroidvania" exploration.', 'Explore a cursed castle and stop the revival of Dracula.', 'Classic Castlevania action-adventure.', 'Castlevania: Portrait of Ruin (Gallery of Labyrinth) features a unique tag-team system. Switch between two protagonists with different abilities as you explore massive paintings to defeat Dracula''s forces on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akumajou-dracula---sougetsu-no-juujika-japan-rev-1', 'NDS', 'Akumajou Dracula - Sougetsu no Juujika (Japan) (Rev 1)', '2006', 'Action', 'Konami', '1', 'Metroidvania', '2D action-platformer with a tactical soul-collecting system.', 'Prevent a mysterious cult from resurrecting the Dark Lord.', 'Acclaimed supernatural action-RPG.', 'Castlevania: Dawn of Sorrow (Sougetsu no Juujika) is a direct sequel to Aria of Sorrow. Collect enemy souls to gain powers and use the "Magic Seal" system with the NDS stylus to defeat powerful bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akumajou-dracula---ubawareta-kokuin-japan', 'NDS', 'Akumajou Dracula - Ubawareta Kokuin (Japan)', '2005', 'Action', 'Konami', '1', 'Metroidvania', '2D action-platformer focusing on magical glyph combat.', 'Use magical glyphs to reclaim your memories and defeat evil.', 'Intense Gothic action-adventure.', 'Castlevania: Order of Ecclesia (Ubawareta Kokuin) introduces a challenging new combat system. Absorb glyphs from enemies and the environment to create powerful attacks in this beautifully gothic NDS title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alc-no-10-punkan-eigo-master---chuukyuu-japan', 'NDS', 'ALC no 10-punkan Eigo Master - Chuukyuu (Japan)', '2008', 'Educational', 'ALC Press', '1', 'Language Learning', 'Interactive English language drills using the NDS stylus.', 'Master intermediate English vocabulary and grammar in 10-minute daily sessions.', 'Intermediate English language trainer for DS.', 'Boost your language skills with ALC no 10-punkan Eigo Master - Chuukyuu. Designed for intermediate learners, this NDS title offers structured 10-minute daily lessons to improve English fluency and comprehension.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alc-no-10-punkan-eigo-master---joukyuu-japan-rev-1', 'NDS', 'ALC no 10-punkan Eigo Master - Joukyuu (Japan) (Rev 1)', '2008', 'Educational', 'ALC Press', '1', 'Language Learning', 'Interactive English language drills using the NDS stylus.', 'Master advanced English vocabulary and grammar in 10-minute daily sessions.', 'Advanced English language trainer for DS.', 'Perfect your English with ALC no 10-punkan Eigo Master - Joukyuu. This advanced NDS training software features intensive daily drills to help players achieve high-level proficiency in English speaking and writing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alc-no-10-punkan-eigo-master---shokyuu-japan', 'NDS', 'ALC no 10-punkan Eigo Master - Shokyuu (Japan)', '2008', 'Educational', 'ALC Press', '1', 'Language Learning', 'Interactive English language drills using the NDS stylus.', 'Master basic English vocabulary and grammar in 10-minute daily sessions.', 'Beginner English language trainer for DS.', 'Start your language journey with ALC no 10-punkan Eigo Master - Shokyuu. This beginner-friendly NDS program uses engaging touch-screen exercises to teach foundational English skills in just 10 minutes a day.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alex-rider---stormbreaker-europe', 'NDS', 'Alex Rider - Stormbreaker (Europe)', '2007', 'Adventure', 'Griptonite Games', '1', 'Action Adventure', 'Stealth-based action and gadget-oriented missions.', 'Infiltrate enemy bases and stop a global cyber-attack as a teen spy.', 'High-stakes spy action based on the film.', 'Step into the world of Alex Rider in Stormbreaker for NDS. Use specialized gadgets, engage in stealth combat, and complete dangerous missions in this official movie-tie-in action adventure.');
