INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alice-in-wonderland-europe-enfrdeesitnl-ndsi-enhanced', 'NDS', 'Alice in Wonderland (Europe) (En,Fr,De,Es,It,Nl) (NDSi Enhanced)', '2010', 'Action', 'Étranges Libellules', '1', 'Platformer', 'Stylized 2D platforming and physics-based puzzle solving.', 'Guide Alice through a twisted Wonderland to defeat the Red Queen.', 'A surreal and artistic puzzle-platformer.', 'Based on the Tim Burton film, Alice in Wonderland for NDS features a unique visual style and time-manipulation mechanics. Use the unique abilities of the Mad Hatter and Cheshire Cat to solve puzzles.');
