INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aliens-in-the-attic-europe-enfrdeesitnl', 'NDS', 'Aliens in the Attic (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Adventure', 'Behaviour Interactive', '1', 'Platformer', 'Action-adventure featuring platforming and combat.', 'Defend the house from a miniature alien invasion.', 'Small-scale heroes vs. alien invaders action.', 'Play as the kids in Aliens in the Attic for NDS. Use unique weapons and teamwork to repel tiny extraterrestrial invaders in this action-packed adaptation of the family adventure film.');
