INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-star-cheer-squad-usa', 'NDS', 'All Star Cheer Squad (USA)', '2008', 'Sports', 'HBK', '1', 'Rhythm', 'Rhythm-based gameplay using the touch screen for stunts.', 'Lead your cheerleading squad to the national championship.', 'High-energy cheerleading and rhythm game.', 'All Star Cheer Squad brings the world of competitive cheer to NDS. Choreograph routines, master rhythm-based stunts, and customize your squad''s look as you climb the ranks to become the best.');
