INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('allied-ace-pilots-europe-enfrdeesit', 'NDS', 'Allied Ace Pilots (Europe) (En,Fr,De,Es,It)', '2007', 'Action', 'City Interactive', '1', 'Arcade Shooter', 'Flight combat simulation set during World War II.', 'Complete aerial missions and engage in dogfights as a fighter pilot.', 'Classic World War II aerial dogfighting.', 'Take to the skies in Allied Ace Pilots. This NDS flight combat game puts you in the cockpit of legendary aircraft, challenging you to complete strategic bombing runs and survive intense air-to-air combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alpha-and-omega-europe-enfrdeesit', 'NDS', 'Alpha and Omega (Europe) (En,Fr,De,Es,It)', '2010', 'Adventure', 'Behaviour Interactive', '1', 'Platformer', 'Puzzle-platforming and mini-games based on the animated film.', 'Help the wolves return home through various natural obstacles.', 'A charming wolf-themed puzzle adventure.', 'Join Humphrey and Kate in Alpha and Omega for NDS. This family-friendly title features varied mini-games and platforming challenges that follow the plot of the animated forest adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alssongdalssong---myeonghwatamheom-ds-korea', 'NDS', 'Alssongdalssong - Myeonghwatamheom DS (Korea)', '2009', 'Adventure', 'Sonnori', '1', 'Story Adventure', 'Educational exploration and puzzle-solving focused on famous art.', 'Explore world-renowned paintings and solve art-related mysteries.', 'An art-history adventure for children.', 'Alssongdalssong - Myeonghwatamheom DS is a Korean educational title that introduces children to fine art. Players solve puzzles within classic masterpieces to learn about history and creativity.');
