INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('americas-test-kitchen---lets-get-cooking-usa', 'NDS', 'America''s Test Kitchen - Let''s Get Cooking (USA)', '2010', 'Cooking', 'Game Mechanics', '1', 'Cooking Simulation', 'Interactive cookbook with step-by-step voice guidance and timers.', 'Master over 300 kitchen-tested recipes from the popular TV show.', 'A comprehensive interactive digital cookbook.', 'America''s Test Kitchen: Let''s Get Cooking for NDS is a professional culinary guide. Featuring a huge library of verified recipes, it uses the touch screen and voice commands to help you cook perfect meals every time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('american-dragon---jake-long---attack-of-the-dark-dragon-usa-enfrdeesit', 'NDS', 'American Dragon - Jake Long - Attack of the Dark Dragon (USA) (En,Fr,De,Es,It)', '2006', 'Action', 'Artificial Mind & Movement', '1', 'Platformer', 'Side-scrolling action-platformer with dragon transformation mechanics.', 'Defeat the Dark Dragon and protect the magical community of NYC.', 'Martial arts and dragon action adventure.', 'Unleash the dragon in American Dragon: Jake Long. This NDS title combines intense hand-to-hand combat with aerial dragon sequences, bringing the hit Disney Channel animated series to life in a portable format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('american-dragon---jake-long-europe-enfrdeesit', 'NDS', 'American Dragon - Jake Long (Europe) (En,Fr,De,Es,It)', '2006', 'Action', 'Artificial Mind & Movement', '1', 'Platformer', 'Side-scrolling action-platformer with dragon transformation mechanics.', 'Defeat the Dark Dragon and protect the magical community of NYC.', 'Martial arts and dragon action adventure.', 'Unleash the dragon in American Dragon: Jake Long. This NDS title combines intense hand-to-hand combat with aerial dragon sequences, bringing the hit Disney Channel animated series to life in a portable format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('american-girl---julie-finds-a-way-usa', 'NDS', 'American Girl - Julie Finds a Way (USA)', '2009', 'Adventure', 'Tornera', '1', 'Narrative', 'Narrative-driven adventure with historical exploration and mini-games.', 'Help Julie navigate life in the 1970s and solve community issues.', 'A historical fiction adventure for girls.', 'Based on the American Girl series, Julie Finds a Way takes players to 1974 San Francisco. Explore the city, complete fun mini-games, and make choices that reflect the character''s courage and historical setting on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('american-girl---kit-mystery-challenge!-usa', 'NDS', 'American Girl - Kit Mystery Challenge! (USA)', '2008', 'Adventure', 'Tornera', '1', 'Narrative', 'Point-and-click mystery solving with hidden object elements.', 'Use Kit''s investigative skills to solve mysteries during the Depression.', 'Historical mystery and detective adventure.', 'Join Kit Kittredge in the Kit Mystery Challenge! Use your detective skills to find clues and interview suspects in this engaging historical mystery for NDS, set in the atmospheric era of the Great Depression.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('amf-bowling-pinbusters!-europe-enfrdeesit', 'NDS', 'AMF Bowling Pinbusters! (Europe) (En,Fr,De,Es,It)', '2005', 'Sports', 'FarSight Studios', '1-4', 'Bowling', 'Sports simulation using the stylus to control ball aim and power.', 'Compete in various bowling alleys and win championship trophies.', 'High-energy arcade bowling simulation.', 'AMF Bowling Pinbusters! brings authentic bowling action to the NDS. Choose from unique characters and master the touch-screen flick mechanics to score strikes and spares across multiple vibrant bowling environments.');
