INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('amici-italy', 'NDS', 'Amici (Italy)', '2006', 'Party', 'Spin-Off', '1-4', 'Social', 'Life simulation and talent competition based on the Italian TV show.', 'Train your character in dance, song, and acting to win the talent show.', 'Official Italian talent show simulation.', 'Amici for NDS allows fans of the popular Italian show to experience the school of talent. Manage your daily training schedule, master artistic mini-games, and climb to the top of the competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('anan-kanshuu---onna-dikara-kinkyuu-up!-ds-japan', 'NDS', 'Anan Kanshuu - Onna Dikara Kinkyuu Up! DS (Japan)', '2009', 'Educational', 'Nintendo', '1', 'Lifestyle', 'Lifestyle training and personality quizzes for women.', 'Improve social skills and personal charm through daily exercises.', 'A women''s lifestyle and self-improvement guide.', 'Anan Kanshuu focuses on "woman power" training. This Japanese NDS title features advice and diagnostic tests based on Anan magazine to help players enhance their social presence and personal charisma.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('anata-dake-no-private-lesson---ds-de-hajimeru-tipness-no-yoga-japan', 'NDS', 'Anata Dake no Private Lesson - DS de Hajimeru Tipness no Yoga (Japan)', '2009', 'Fitness', 'Tipness', '1', 'Wellness', 'Guided yoga sessions using the NDS screens for visual instruction.', 'Practice yoga and improve flexibility with a virtual instructor.', 'A portable yoga and wellness trainer.', 'Turn your NDS into a private studio with Tipness no Yoga. Follow professional instructors through various poses and routines designed to promote relaxation and physical health through interactive lessons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('anata-mo-ds-de-classic-kiite-mimasenka-japan', 'NDS', 'Anata mo DS de Classic Kiite Mimasenka (Japan)', '2008', 'Music', 'Nintendo', '1', 'Classical Listening', 'Music player and educational software for classical masterpieces.', 'Listen to and learn the history of famous classical music pieces.', 'A digital classical music library and guide.', 'Anata mo DS de Classic Kiite Mimasenka is a musical journey for NDS. Enjoy high-quality recordings of famous works while learning about the composers and the historical context behind the music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ancient-spirits---columbus-legacy-europe-enfrdenl', 'NDS', 'Ancient Spirits - Columbus'' Legacy (Europe) (En,Fr,De,Nl)', '2009', 'Adventure', 'Fun Labs', '1', 'Action Adventure', 'Hidden object adventure with puzzle-solving and exploration.', 'Uncover the truth behind the legacy of Christopher Columbus.', 'Historical hidden object and mystery game.', 'Embark on a grand quest in Ancient Spirits: Columbus'' Legacy. Search for legendary artifacts and solve intricate puzzles to reveal secrets buried for centuries in this atmospheric NDS adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('angel-cat-sugar-europe-enfrdeesit', 'NDS', 'Angel Cat Sugar (Europe) (En,Fr,De,Es,It)', '2008', 'Adventure', 'Art Co. Ltd.', '1', 'Cute Adventure', 'Casual mini-games and social interactions in a cute world.', 'Complete tasks and play with Angel Cat Sugar and her friends.', 'A charming and relaxing character-based game.', 'Enter the sweet world of Angel Cat Sugar. Designed for younger players, this NDS title features gentle mini-games, puzzle-solving, and a heartwarming aesthetic based on the famous Sanrio-style character.');
