INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('angelique-duet-japan', 'NDS', 'Angelique Duet (Japan)', '2006', 'Strategy', 'Koei', '1', 'Otome Strategy', 'Visual novel and dating simulation with fantasy elements.', 'Balance royal duties and relationships to become the Queen.', 'Classic Otome fantasy romance adventure.', 'Angelique Duet brings the pioneering Otome series to NDS. Interact with handsome guardians and manage your planetary development as you compete to become the next ruler of the universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-boxing-usa', 'NDS', 'Animal Boxing (USA)', '2009', 'Fighting', 'Zen Studios', '1-2', 'Casual Fighting', 'First-person boxing using a unique touch-screen control scheme.', 'Fight through the ranks of animal boxers to become the champion.', 'Quirky and fast-paced animal boxing action.', 'Animal Boxing features a unique way to play: hold the NDS upside down! Use the stylus to throw punches and hooks in this creative and humorous take on the sport, featuring a cast of wild animal opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-genius-europe-enfrdeesitnlsvnoda', 'NDS', 'Animal Genius (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2007', 'Educational', 'Black Lantern Studios', '1', 'Brain Training', 'Educational trivia and mini-games focused on animal biology.', 'Earn "Animal Genius" status by mastering facts about wildlife.', 'An interactive animal encyclopedia and quiz.', 'Animal Genius for NDS challenges your knowledge of the natural world. Complete maze games and quizzes to unlock detailed information about different habitats and the animals that live there.');
