INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-kororo-europe-enfrdeesit', 'NDS', 'Animal Kororo (Europe) (En,Fr,De,Es,It)', '2009', 'Adventure', 'Fun Labs', '1', 'Casual Adventure', 'Puzzle-solving with physics and gravity mechanics.', 'Rotate the world to clear animals and solve environmental puzzles.', 'A cute and gravity-defying puzzle game.', 'Animal Kororo (also known as Rolling Zoo) challenges you to move cute animals by tilting the environment. Match identical animals to clear levels in this colorful and brain-teasing NDS puzzle title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-paradise---wild-usa-enfres', 'NDS', 'Animal Paradise - Wild (USA) (En,Fr,Es)', '2009', 'Simulation', 'Eden Games', '1', 'Wildlife Simulation', 'Virtual pet simulation and photography in a wildlife park.', 'Care for wild animals and take professional photos for your album.', 'A wildlife sanctuary simulation for kids.', 'Animal Paradise: Wild takes you to a sanctuary where you can interact with lions, pandas, and more. Bond with the animals and capture their best moments in this photography-focused pet sim for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-paradise-europe-enfrdeesitnl', 'NDS', 'Animal Paradise (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Simulation', 'Eden Games', '1', 'Wildlife Simulation', 'Virtual pet interaction and animal care mini-games.', 'Visit a farm and make friends with all the resident animals.', 'A cute and interactive animal friendship game.', 'Animal Paradise is all about making friends with nature. Use the NDS touch screen to pet, feed, and play with over 18 different animals, earning their trust to unlock new areas and secrets.');
