INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-world---big-cats-europe-enfrdeesit', 'NDS', 'Animal World - Big Cats (Europe) (En,Fr,De,Es,It)', '2009', 'Educational', 'Fun Labs', '1', 'Wildlife', 'Educational exploration and mini-games about predatory cats.', 'Learn facts and complete challenges related to lions and tigers.', 'An educational guide to big cats.', 'Animal World: Big Cats is a digital interactive encyclopedia for NDS. Explore the lives of nature''s greatest predators through engaging mini-games and high-quality educational content.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-world---dinosaurs-europe-enfrdeesit', 'NDS', 'Animal World - Dinosaurs (Europe) (En,Fr,De,Es,It)', '2009', 'Educational', 'Fun Labs', '1', 'Prehistory', 'Educational exploration and mini-games about prehistoric life.', 'Discover facts about dinosaurs and complete fossil-themed tasks.', 'A prehistoric educational dinosaur guide.', 'Step back in time with Animal World: Dinosaurs. This NDS title combines history and fun, allowing kids to learn about different species through interactive exploration and paleontology puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animaniacs---lights-camera-action!-europe-enfrdeesit', 'NDS', 'Animaniacs - Lights, Camera, Action! (Europe) (En,Fr,De,Es,It)', '2005', 'Action', 'Warthog Games', '1', 'Platformer', 'Side-scrolling platforming with puzzle-solving elements.', 'Help the Warner siblings escape the movie studio and stop the director.', 'Wacky platforming based on the hit cartoon.', 'Animaniacs: Lights, Camera, Action! brings the chaos of Yakko, Wakko, and Dot to the NDS. Use their unique abilities to solve puzzles and cause mayhem across various movie sets.');
