INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ankh---curse-of-the-scarab-king-europe-enesitnlplru', 'NDS', 'Ankh - Curse of the Scarab King (Europe) (En,Es,It,Nl,Pl,Ru)', '2007', 'Adventure', 'Deck13', '1', 'Point and Click', 'Point-and-click adventure with puzzle-solving and inventory management.', 'Help Assil survive a deadly curse in ancient Egypt.', 'A humorous ancient Egyptian adventure.', 'Ankh - Curse of the Scarab King brings classic point-and-click gameplay to the NDS. Explore a vibrant 3D version of ancient Cairo, solve witty puzzles, and enjoy a comedic narrative full of colorful characters and historical satire.');
