INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ankys-ruiterschool-europe-frnl', 'NDS', 'Anky''s Ruiterschool (Europe) (Fr,Nl)', '2008', 'Simulation', 'Independent Arts', '1', 'Horse Riding', 'Equestrian simulation with horse care and riding lessons.', 'Master dressage and show jumping at the famous riding school.', 'Professional horse riding training sim.', 'Join the world of Anky van Grunsven in Anky''s Ruiterschool. This NDS title focuses on realistic dressage and horse management, allowing players to groom, train, and compete with their horses under professional guidance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('anna-&-die-liebe-germany', 'NDS', 'Anna & die Liebe (Germany)', '2009', 'Simulation', 'Radical Fish Games', '1', 'Romance Simulation', 'Visual novel and life simulation based on the German TV show.', 'Navigate professional and romantic life in a fashion agency.', 'Official TV show-based romance adventure.', 'Anna & die Liebe lets you experience the story of the hit telenovela on NDS. Make critical life choices, engage in office drama, and find true love while managing your career in the competitive fashion industry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('annie-mg-schmidts-pluk-van-de-petteflet-netherlands', 'NDS', 'Annie M.G. Schmidt''s Pluk van de Petteflet (Netherlands)', '2008', 'Adventure', 'ClockStone', '1', 'Storybook', 'Mini-game collection and interactive storybook for children.', 'Help Pluk navigate the city and help his animal friends.', 'A charming Dutch children''s adventure.', 'Based on the beloved Dutch character, Pluk van de Petteflet features a series of engaging mini-games. Children explore the world of Annie M.G. Schmidt, completing tasks and interacting with iconic characters from the book.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('annie-no-atelier---sera-tou-no-renkinjutsushi-japan', 'NDS', 'Annie no Atelier - Sera-tou no Renkinjutsushi (Japan)', '2009', 'RPG', 'Gust', '1', 'JRPG', 'Turn-based RPG with heavy focus on alchemy and crafting.', 'Manage a resort island and master the art of alchemy.', 'Alchemy-based management and RPG.', 'Annie no Atelier: Sera-tou no Renkinjutsushi is a charming entry in the Atelier series for NDS. Combine resource gathering with deep crafting mechanics as you work to develop a thriving island and master complex alchemical recipes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('anno---create-a-new-world-europe-enfrdeesit', 'NDS', 'Anno - Create a New World (Europe) (En,Fr,De,Es,It)', '2007', 'Strategy', 'Related Designs', '1-4', 'City Building', 'Real-time strategy and city-building simulation.', 'Settle new islands and establish a thriving trade empire.', 'Deep handheld strategy and city builder.', 'Anno: Create a New World brings the acclaimed strategy series to the NDS. Manage resources, balance the needs of your citizens, and navigate diplomatic relations as you build a powerful maritime civilization from scratch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('anno-1701---dawn-of-discovery-europe-enfrdeesitnl', 'NDS', 'Anno 1701 - Dawn of Discovery (Europe) (En,Fr,De,Es,It,Nl)', '2006', 'Strategy', 'Related Designs', '1-4', 'City Building', 'Real-time strategy and city-building simulation.', 'Settle new islands and establish a thriving trade empire.', 'Deep handheld strategy and city builder.', 'Anno 1701: Dawn of Discovery offers a comprehensive city-building experience on NDS. Featuring an intuitive touch-screen interface, it challenges players to colonize uncharted territories and build prosperous 18th-century settlements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('anno-1701---dawn-of-discovery-usa-enfres', 'NDS', 'Anno 1701 - Dawn of Discovery (USA) (En,Fr,Es)', '2006', 'Strategy', 'Related Designs', '1-4', 'City Building', 'Real-time strategy and city-building simulation.', 'Settle new islands and establish a thriving trade empire.', 'Deep handheld strategy and city builder.', 'Anno 1701: Dawn of Discovery offers a comprehensive city-building experience on NDS. Featuring an intuitive touch-screen interface, it challenges players to colonize uncharted territories and build prosperous 18th-century settlements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('annyeong!-haemtori---haemtoriwa-banggabangga-chingudeul-korea', 'NDS', 'Annyeong! Haemtori - Haemtoriwa BanggaBangga Chingudeul (Korea)', '2009', 'Adventure', 'Fiction Factory', '1', 'Casual Adventure', 'Casual mini-games featuring Hamtaro and his friends.', 'Play and interact with the Ham-Hams in various activities.', 'Cute hamster-themed mini-game collection.', 'Annyeong! Haemtori brings the world of Hamtaro to the NDS. This Korean release features colorful mini-games designed for younger players, focusing on friendship and simple interactive tasks with the famous hamsters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('another-code---futatsu-no-kioku-japan', 'NDS', 'Another Code - Futatsu no Kioku (Japan)', '2005', 'Adventure', 'Cing', '1', 'Mystery', 'Point-and-click mystery with dual-screen puzzle solving.', 'Uncover the secrets of Blood Edward Island and find your father.', 'Atmospheric mystery adventure game.', 'Another Code (Trace Memory) utilizes every feature of the NDS. Solve complex puzzles that bridge the past and present as you guide Ashley Mizuki Robbins through a haunting estate to solve a family mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('another-code---two-memories-europe-enfrdeesit', 'NDS', 'Another Code - Two Memories (Europe) (En,Fr,De,Es,It)', '2005', 'Adventure', 'Cing', '1', 'Mystery', 'Point-and-click mystery with dual-screen puzzle solving.', 'Uncover the secrets of Blood Edward Island and find your father.', 'Atmospheric mystery adventure game.', 'Another Code (Trace Memory) utilizes every feature of the NDS. Solve complex puzzles that bridge the past and present as you guide Ashley Mizuki Robbins through a haunting estate to solve a family mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('another-time-another-leaf---kagami-no-naka-no-tantei-japan', 'NDS', 'Another Time, Another Leaf - Kagami no Naka no Tantei (Japan)', '2008', 'Adventure', 'Arc System Works', '1', 'Visual Novel', 'Mystery adventure visual novel with a parallel world mechanic.', 'Solve a series of crimes by investigating two different timelines.', 'Supernatural detective visual novel.', 'Another Time, Another Leaf features a unique investigation mechanic where players switch between parallel worlds. Solve intricate urban legends and mysteries by finding clues that only exist in one reality or the other.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('anpanman-to-asobo---abc-kyoushitsu-japan', 'NDS', 'Anpanman to Asobo - ABC Kyoushitsu (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Alphabet Learning', 'Educational mini-games focusing on the English alphabet.', 'Learn the English alphabet with Anpanman and friends.', 'Preschool English educational trainer.', 'Anpanman to Asobo - ABC Kyoushitsu is a fun learning tool for toddlers. Use the NDS touch screen to trace letters and learn basic English vocabulary alongside Japan’s most beloved children''s hero.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('anpanman-to-asobo---aiueo-kyoushitsu-japan', 'NDS', 'Anpanman to Asobo - Aiueo Kyoushitsu (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Alphabet Learning', 'Educational mini-games focusing on the Japanese Hiragana.', 'Master the Japanese alphabet through fun drills.', 'Preschool Japanese educational trainer.', 'Anpanman to Asobo - Aiueo Kyoushitsu makes learning Hiragana engaging for children. Through tracing exercises and sound recognition games, kids learn the foundations of the Japanese language in a colorful environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('anpanman-to-asobo---aiueo-kyoushitsu-japan-rev-1', 'NDS', 'Anpanman to Asobo - Aiueo Kyoushitsu (Japan) (Rev 1)', '2007', 'Educational', 'Nintendo', '1', 'Alphabet Learning', 'Educational mini-games focusing on the Japanese Hiragana.', 'Master the Japanese alphabet through fun drills.', 'Preschool Japanese educational trainer.', 'Anpanman to Asobo - Aiueo Kyoushitsu makes learning Hiragana engaging for children. Through tracing exercises and sound recognition games, kids learn the foundations of the Japanese language in a colorful environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('anpanman-to-asobo---aiueo-kyoushitsu-dx-japan', 'NDS', 'Anpanman to Asobo - Aiueo Kyoushitsu DX (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Alphabet Learning', 'Enhanced educational drills and more content for early learners.', 'Complete a wide variety of literacy and logic mini-games.', 'Comprehensive Anpanman learning pack.', 'This Deluxe version of the Anpanman educational series offers expanded mini-games. It covers basic literacy and counting, providing a safe and educational digital playground for young Nintendo DS users.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('anpanman-to-touch-de-waku-waku-training-japan', 'NDS', 'Anpanman to Touch de Waku Waku Training (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Training', 'Educational mini-games for cognitive and physical coordination.', 'Complete a variety of "Waku Waku" training challenges.', 'Child development and training games.', 'Anpanman to Touch de Waku Waku Training focuses on reflex and coordination. Using the stylus, children help Anpanman through various scenarios that build motor skills and basic logic in an interactive way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ant-nation-europe-enfrdeesit', 'NDS', 'Ant Nation (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Pocket House', '1', 'Colony Simulation', 'God-sim and strategy where you manage an ant colony.', 'Protect and grow your ant hill while defeating predators.', 'Strategic insect colony simulator.', 'Ant Nation turns your NDS into a laboratory. Manipulate your ants, subject them to "training," and build an unstoppable colony to survive against rival insects and environmental hazards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ant-nation-usa-enfres', 'NDS', 'Ant Nation (USA) (En,Fr,Es)', '2008', 'Simulation', 'Pocket House', '1', 'Colony Simulation', 'God-sim and strategy where you manage an ant colony.', 'Protect and grow your ant hill while defeating predators.', 'Strategic insect colony simulator.', 'Ant Nation turns your NDS into a laboratory. Manipulate your ants, subject them to "training," and build an unstoppable colony to survive against rival insects and environmental hazards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aodon-ds---hanabi-no-kiwami-&-hanabi-no-takumi-japan', 'NDS', 'Aodon DS - Hanabi no Kiwami & Hanabi no Takumi (Japan)', '2009', 'Action', 'Success', '1', 'Arcade Action', 'Pachinko and slot machine simulation.', 'Master the Aodon slot machines and win virtual credits.', 'Japanese Pachislot simulator.', 'Aodon DS provides a realistic simulation of the popular Hanabi slot machines. Test your timing and luck on authentic digital versions of Japan''s most famous casino-style arcade machines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('apassionata---die-galanacht-der-pferde---meine-show-europe-enfrdeesit', 'NDS', 'Apassionata - Die Galanacht der Pferde - Meine Show (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'BitComposer Games', '1', 'Horse Show', 'Management and show planning simulation for horse lovers.', 'Organize and perform a world-class equestrian show.', 'Horse show management and performance sim.', 'Apassionata lets you step behind the scenes of the famous gala. Train horses, choreograph musical numbers, and manage the logistics of a spectacular equestrian show in this unique creative simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('apathy---narukami-gakuen-toshi-densetsu-tantei-kyoku-japan', 'NDS', 'Apathy - Narukami Gakuen Toshi Densetsu Tantei Kyoku (Japan)', '2008', 'Adventure', 'Acquire', '1', 'Horror Visual Novel', 'Visual novel mystery based on school urban legends.', 'Investigate supernatural occurrences at Narukami Academy.', 'Dark school-mystery visual novel.', 'Apathy - Narukami Gakuen Toshi Densetsu Tantei Kyoku is a horror-tinged detective game. Uncover the truth behind terrifying school myths through deep narrative paths and investigation mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('apollo-justice---ace-attorney-europe', 'NDS', 'Apollo Justice - Ace Attorney (Europe)', '2007', 'Adventure', 'Capcom', '1', 'Visual Novel', 'Legal drama and courtroom simulation with investigation.', 'Defend your clients in court and find the real culprits.', 'The fourth major Ace Attorney game.', 'Apollo Justice: Ace Attorney introduces a new protagonist to the series. Use the "Perceive" system to spot nervous tics and use forensic evidence to solve complex murder cases in this acclaimed legal thriller.');
