INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('appare!-shougi-jiisan---washi-to-shoubu-ja-japan', 'NDS', 'Appare! Shougi Jiisan - Washi to Shoubu ja (Japan)', '2009', 'Board Game', 'Success', '1-2', 'Traditional', 'Strategic Shougi board gameplay with a humorous twist.', 'Defeat the "Shougi Grandpa" and improve your skills.', 'Traditional Japanese Shougi with a twist.', 'Appare! Shougi Jiisan offers a friendly yet challenging way to play Japanese chess. Face off against the master Shougi Grandpa in a game that combines traditional strategy with a lighthearted, elderly-themed presentation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aqua-panic!-europe-enfrdeesitnlpt', 'NDS', 'Aqua Panic! (Europe) (En,Fr,De,Es,It,Nl,Pt)', '2008', 'Puzzle', 'Eko Software', '1', 'Arcade Puzzle', 'Physics-based puzzle solving involving water and sea life.', 'Guide your fish safely to the exit by manipulating the environment.', 'A creative aquatic physics puzzle game.', 'Aqua Panic! challenges you to save schools of fish. Use various tools to redirect water flow and avoid predators in this colorful and brain-teasing puzzle title that requires careful planning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aqua-panic!-usa-enfres', 'NDS', 'Aqua Panic! (USA) (En,Fr,Es)', '2008', 'Puzzle', 'Eko Software', '1', 'Arcade Puzzle', 'Physics-based puzzle solving involving water and sea life.', 'Guide your fish safely to the exit by manipulating the environment.', 'A creative aquatic physics puzzle game.', 'Aqua Panic! challenges you to save schools of fish. Use various tools to redirect water flow and avoid predators in this colorful and brain-teasing puzzle title that requires careful planning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aquarium-by-ds-europe-enfrdeesit', 'NDS', 'Aquarium by DS (Europe) (En,Fr,De,Es,It)', '2007', 'Simulation', 'DS Software', '1', 'Aquarium Simulation', 'Virtual aquarium management and fish breeding.', 'Create and maintain a beautiful underwater ecosystem.', 'A relaxing virtual fish tank simulator.', 'Aquarium by DS allows you to design and manage your own digital fish tank. Choose from various species, decorate your environment, and maintain the water quality to keep your aquatic pets thriving in this peaceful simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aquarium-by-ds-usa', 'NDS', 'Aquarium by DS (USA)', '2007', 'Simulation', 'DS Software', '1', 'Aquarium Simulation', 'Virtual aquarium management and fish breeding.', 'Create and maintain a beautiful underwater ecosystem.', 'A relaxing virtual fish tank simulator.', 'Aquarium by DS allows you to design and manage your own digital fish tank. Choose from various species, decorate your environment, and maintain the water quality to keep your aquatic pets thriving in this peaceful simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arabians-lost---the-engagement-on-desert-japan', 'NDS', 'Arabians Lost - The Engagement on Desert (Japan)', '2007', 'Adventure', 'Arc System Works', '1', 'Visual Novel', 'Otome visual novel with dating and negotiation elements.', 'Navigate romantic relationships while escaping a desert kingdom.', 'A desert-themed romance visual novel.', 'Arabians Lost: The Engagement on Desert is a rich Otome experience. Play as a princess who must find a way to avoid an arranged marriage by engaging with various suitors in a high-stakes narrative filled with drama and romance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aranuri---badachingudeulkkwa-hamkke-mandeuneun-sesang-korea', 'NDS', 'Aranuri - Badachingudeulkkwa hamkke Mandeuneun Sesang (Korea)', '2009', 'Educational', 'Sonnori', '1', 'Edutainment', 'Creative world-building and social mini-games for children.', 'Build and decorate a digital world with sea animal friends.', 'A creative Korean children''s sandbox game.', 'Aranuri allows young players to express their creativity. Build a unique world, interact with adorable sea creature friends, and participate in educational mini-games designed to foster imagination and social skills on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arashi-no-yoru-ni-japan', 'NDS', 'Arashi no Yoru ni (Japan)', '2005', 'Adventure', 'Group SNE', '1', 'Story Adventure', 'Action-adventure based on the animated film and book.', 'Help a goat and a wolf survive their journey together.', 'A story-driven adventure about unlikely friends.', 'Arashi no Yoru ni (One Stormy Night) follows the touching story of Mei and Gabu. Navigate through various environments and overcome obstacles by utilizing the unique bond between these two natural enemies in a beautifully styled NDS world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arashi-no-yoru-ni-japan-rev-1', 'NDS', 'Arashi no Yoru ni (Japan) (Rev 1)', '2005', 'Adventure', 'Group SNE', '1', 'Story Adventure', 'Action-adventure based on the animated film and book.', 'Help a goat and a wolf survive their journey together.', 'A story-driven adventure about unlikely friends.', 'Arashi no Yoru ni (One Stormy Night) follows the touching story of Mei and Gabu. Navigate through various environments and overcome obstacles by utilizing the unique bond between these two natural enemies in a beautifully styled NDS world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arasuji-de-kitaeru---hayamimi-no-susume-ds-japan', 'NDS', 'Arasuji de Kitaeru - Hayamimi no Susume DS (Japan)', '2008', 'Educational', 'IE Institute', '1', 'Reading Training', 'Educational software focused on summarizing and listening skills.', 'Master the art of summarizing information quickly.', 'A professional skill-building educational tool.', 'Arasuji de Kitaeru helps players improve their cognitive speed and listening comprehension. Through various drills, you learn how to identify key points and summarize complex information, a valuable skill for academic and professional life.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arasuji-de-oboeru-sokudoku-no-susume-ds-japan', 'NDS', 'Arasuji de Oboeru Sokudoku no Susume DS (Japan)', '2008', 'Educational', 'IE Institute', '1', 'Speed Reading', 'Speed reading training and literary comprehension drills.', 'Increase your reading speed while retaining information.', 'A comprehensive speed reading trainer.', 'Arasuji de Oboeru Sokudoku no Susume DS offers a structured curriculum to boost reading proficiency. Use the NDS touch screen to practice rapid scanning and comprehension techniques using classic literature as your training material.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('archime-ds-japan-enja', 'NDS', 'Archime DS (Japan) (En,Ja)', '2007', 'Puzzle', 'Aruze', '1', 'Logic Puzzle', '2D platforming and creative level editing.', 'Complete challenging levels or create your own to share.', 'A classic-style platformer with an editor.', 'Archime DS is a treat for fans of retro platformers. Not only can you play through a variety of challenging stages, but the built-in editor allows you to design custom levels, extending the life of this creative handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arctic-tale-europe-enfrdeesit', 'NDS', 'Arctic Tale (Europe) (En,Fr,De,Es,It)', '2007', 'Adventure', 'Behaviour Interactive', '1', 'Family Adventure', 'Educational adventure based on the National Geographic film.', 'Guide a polar bear and a walrus through the changing Arctic.', 'An educational nature adventure for kids.', 'Based on the documentary, Arctic Tale follows the life cycles of a polar bear cub and a walrus pup. Learn about the challenges of the Arctic environment while completing mini-games and exploring the frozen wilderness on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arctic-tale-usa', 'NDS', 'Arctic Tale (USA)', '2007', 'Adventure', 'Behaviour Interactive', '1', 'Family Adventure', 'Educational adventure based on the National Geographic film.', 'Guide a polar bear and a walrus through the changing Arctic.', 'An educational nature adventure for kids.', 'Based on the documentary, Arctic Tale follows the life cycles of a polar bear cub and a walrus pup. Learn about the challenges of the Arctic environment while completing mini-games and exploring the frozen wilderness on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('are-you-smarter-than-a-10-year-old---the-official-nintendo-ds-game-europe', 'NDS', 'Are You Smarter than a 10 Year Old - The Official Nintendo DS Game (Europe)', '2008', 'Quiz', 'Ludia', '1-4', 'Game Show', 'Trivia quiz gameplay based on the hit TV game show.', 'Prove your knowledge by answering primary school questions.', 'The official game of the hit trivia show.', 'Are You Smarter than a 10 Year Old? brings the tension of the classroom to your NDS. Face off against a panel of school kids and test your knowledge in subjects like history, math, and science to win the top prize.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('are-you-smarter-than-a-5th-grader---game-time-usa', 'NDS', 'Are You Smarter than a 5th Grader - Game Time (USA)', '2009', 'Quiz', 'Ludia', '1-4', 'Game Show', 'Trivia quiz gameplay based on the hit TV game show.', 'Answer elementary-level questions to win virtual cash.', 'High-stakes elementary school trivia.', 'Are You Smarter than a 5th Grader: Game Time features thousands of questions across various school subjects. Test your wits solo or compete against friends to see who actually remembered what they learned in grade school.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('are-you-smarter-than-a-5th-grader---make-the-grade-usa', 'NDS', 'Are You Smarter than a 5th Grader - Make the Grade (USA)', '2008', 'Quiz', 'Ludia', '1-4', 'Game Show', 'Trivia quiz gameplay based on the hit TV game show.', 'Answer elementary-level questions to win virtual cash.', 'High-stakes elementary school trivia.', 'Are You Smarter than a 5th Grader: Make the Grade offers a competitive take on the TV show. Prove your academic prowess across multiple difficulty levels and unlock achievements as you climb to the top of the class.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('are-you-smarter-than-a-5th-grader-australia', 'NDS', 'Are You Smarter than a 5th Grader (Australia)', '2008', 'Quiz', 'Ludia', '1-4', 'Game Show', 'Trivia quiz gameplay based on the hit TV game show.', 'Answer elementary-level questions to win virtual cash.', 'High-stakes elementary school trivia.', 'Are You Smarter than a 5th Grader? (Australia) brings the localized version of the global hit show to your NDS. Challenge yourself with Australian-specific trivia and standard school subjects in this addictive quiz format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('are-you-smarter-than-a-5th-grader-usa', 'NDS', 'Are You Smarter than a 5th Grader (USA)', '2007', 'Quiz', 'Ludia', '1-4', 'Game Show', 'Trivia quiz gameplay based on the hit TV game show.', 'Answer elementary-level questions to win virtual cash.', 'High-stakes elementary school trivia.', 'Are You Smarter than a 5th Grader? for NDS captures the fun and pressure of the TV show. Work your way through the grades and use your "cheats" wisely to prove that you are indeed smarter than an average 10-year-old.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arkanoid-ds-europe-enfrdeesit', 'NDS', 'Arkanoid DS (Europe) (En,Fr,De,Es,It)', '2007', 'Action', 'Taito', '1', 'Arcade', 'Arcade brick-breaking action with unique power-ups.', 'Clear all blocks using a paddle and energy ball.', 'A modern update of the arcade classic.', 'Arkanoid DS revitalizes the legendary franchise. Use the touch screen or the optional paddle controller to clear stages, defeat bosses, and enjoy a variety of game modes that blend classic gameplay with modern visual flair.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arkanoid-ds-japan', 'NDS', 'Arkanoid DS (Japan)', '2007', 'Action', 'Taito', '1', 'Arcade', 'Arcade brick-breaking action with unique power-ups.', 'Clear all blocks using a paddle and energy ball.', 'A modern update of the arcade classic.', 'Arkanoid DS revitalizes the legendary franchise. Use the touch screen or the optional paddle controller to clear stages, defeat bosses, and enjoy a variety of game modes that blend classic gameplay with modern visual flair.');
