INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men---soldiers-of-misfortune-europe-enfrdeesit', 'NDS', 'Army Men - Soldiers of Misfortune (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'Global Star Software', '1', 'Action Shooter', 'Third-person action-adventure featuring green plastic soldiers.', 'Protect the household from a chaotic toy invasion.', 'Fun, small-scale military action.', 'Army Men: Soldiers of Misfortune lets you play as Timmy, shrunk down to toy size. Join the Green Army to battle the Tan Army across household environments like the kitchen and bedroom in this imaginative action title for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men---soldiers-of-misfortune-usa', 'NDS', 'Army Men - Soldiers of Misfortune (USA)', '2008', 'Action', 'Global Star Software', '1', 'Action Shooter', 'Third-person action-adventure featuring green plastic soldiers.', 'Protect the household from a chaotic toy invasion.', 'Fun, small-scale military action.', 'Army Men: Soldiers of Misfortune lets you play as Timmy, shrunk down to toy size. Join the Green Army to battle the Tan Army across household environments like the kitchen and bedroom in this imaginative action title for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('around-the-world-in-80-days-europe-enfrde', 'NDS', 'Around the World in 80 Days (Europe) (En,Fr,De)', '2007', 'Adventure', 'Sproing Interactive', '1', 'Puzzle Adventure', 'Match-3 puzzle gameplay with adventure elements.', 'Solve puzzles to complete Phileas Fogg''s journey around the globe.', 'A classic adventure-themed puzzle game.', 'Around the World in 80 Days brings the Jules Verne classic to life through addictive match-3 mechanics. Solve challenging boards to find items and progress through iconic cities in a race against the clock.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('around-the-world-in-80-days-europe-enfrnl', 'NDS', 'Around the World in 80 Days (Europe) (En,Fr,Nl)', '2007', 'Adventure', 'Sproing Interactive', '1', 'Puzzle Adventure', 'Match-3 puzzle gameplay with adventure elements.', 'Solve puzzles to complete Phileas Fogg''s journey around the globe.', 'A classic adventure-themed puzzle game.', 'Around the World in 80 Days brings the Jules Verne classic to life through addictive match-3 mechanics. Solve challenging boards to find items and progress through iconic cities in a race against the clock.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('art---das-kunstmagazin-puzzle---echter-puzzlespass-fuer-unterwegs-europe-enfrdeesit', 'NDS', 'Art - Das Kunstmagazin Puzzle - Echter Puzzlespass fuer Unterwegs (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'Tivola', '1', 'Art Puzzle', 'Digital jigsaw puzzle simulation with high-quality art themes.', 'Complete intricate puzzles based on famous artworks.', 'A premium digital jigsaw puzzle collection.', 'Art: Das Kunstmagazin Puzzle offers a sophisticated puzzling experience. Assemble high-resolution images of famous art pieces on your NDS, featuring various difficulty levels and a relaxing atmosphere for art lovers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('art-academy-europe-enfrdeesit-ndsi-enhanced', 'NDS', 'Art Academy (Europe) (En,Fr,De,Es,It) (NDSi Enhanced)', '2009', 'Educational', 'Nintendo', '1', 'Art Training', 'Realistic art studio simulation with interactive lessons.', 'Learn real-world drawing and painting techniques.', 'A professional-grade art education tool.', 'Art Academy transforms your NDS into a portable canvas. Follow step-by-step tutorials on color theory, shading, and perspective to create stunning digital paintings that translate to real-life artistic skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('art-style---pictobits-usa', 'NDS', 'Art Style - PiCTOBiTS (USA)', '2009', 'Puzzle', 'Skip Ltd.', '1', 'Minimalist Arcade', 'Rhythm-based puzzle gameplay with a retro aesthetic.', 'Clear colored bits to reveal hidden pixel-art pictures.', 'A unique 8-bit style rhythm puzzle.', 'Art Style: PiCTOBiTS combines classic NES-style visuals with addictive puzzle-action. Use the touch screen to move blocks and clear the screen in time with catchy chiptune music to unlock classic Nintendo character art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arthur-and-the-invisibles---the-game-usa-enfres', 'NDS', 'Arthur and the Invisibles - The Game (USA) (En,Fr,Es)', '2006', 'Action', 'Étranges Libellules', '1', 'Action Adventure', 'Action-adventure with platforming, racing, and mini-games.', 'Help Arthur save the Invisibles'' world from destruction.', 'A diverse adventure based on the movie.', 'Arthur and the Invisibles brings the fantastical world of the film to your handheld. Experience a mix of gameplay styles including 3D exploration and fast-paced vehicle segments as you battle the forces of Maltazard.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arthur-and-the-minimoys-europe-enfrdeesitnl', 'NDS', 'Arthur and the Minimoys (Europe) (En,Fr,De,Es,It,Nl)', '2006', 'Action', 'Étranges Libellules', '1', 'Action Adventure', 'Action-adventure with platforming, racing, and mini-games.', 'Help Arthur save the Invisibles'' world from destruction.', 'A diverse adventure based on the movie.', 'Arthur and the Invisibles brings the fantastical world of the film to your handheld. Experience a mix of gameplay styles including 3D exploration and fast-paced vehicle segments as you battle the forces of Maltazard.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arthur-and-the-revenge-of-maltazard-europe-enfrdeesitnl', 'NDS', 'Arthur and the Revenge of Maltazard (Europe) (En,Fr,De,Es,It,Nl)', '2010', 'Action', 'Wide Games', '1', 'Action Adventure', 'Mini-game collection and story-based adventure.', 'Complete various party games to progress through the film''s plot.', 'A fun, mini-game focused movie tie-in.', 'Arthur and the Revenge of Maltazard is packed with over 30 wacky mini-games. Cooperate with friends or play solo to help Arthur and the Minimoys save their village in this colorful and entertaining NDS adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aruite-wakaru---seikatsu-rhythm-ds-japan', 'NDS', 'Aruite Wakaru - Seikatsu Rhythm DS (Japan)', '2008', 'Educational', 'Nintendo', '1', 'Lifestyle Training', 'Fitness and lifestyle tracking using the NDS pedometer.', 'Track your daily steps and improve your physical activity.', 'A daily step-counting and lifestyle manager.', 'Aruite Wakaru uses the NDS pedometer accessory to track your movement. Set goals, view charts of your progress, and participate in mini-games that reward your real-world physical activity to maintain a healthy lifestyle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ash---archaic-sealed-heat-japan', 'NDS', 'ASH - Archaic Sealed Heat (Japan)', '2007', 'RPG', 'Mistwalker', '1', 'JRPG', 'Tactical turn-based RPG with 3D combat and strategic movement.', 'Command a team of warriors to stop a rising ancient threat.', 'A deep and strategic fantasy RPG.', 'ASH: Archaic Sealed Heat is a visually impressive tactical RPG for NDS. Master the complex "Team Battle" system and lead your party through a cinematic story involving fallen warriors resurrected by mysterious flames.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asonde-igo-ga-sarani-tsuyoku-naru!---ginsei-igo-ds---chuukyuu-hen-japan', 'NDS', 'Asonde Igo ga Sarani Tsuyoku Naru! - Ginsei Igo DS - Chuukyuu Hen (Japan)', '2008', 'Board Game', 'SilverStar Japan', '1-2', 'Traditional', 'Strategic board gameplay with interactive tutorials.', 'Master intermediate Go techniques and defeat advanced AI.', 'Intermediate Go (Igo) trainer for DS.', 'Enhance your Go skills with Asonde Igo ga Sarani Tsuyoku Naru! Part of the Ginsei Igo series, this NDS title provides intermediate lessons and a powerful engine to help players transition from basics to advanced strategic mastery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asonde-igo-ga-tsuyoku-naru!---ginsei-igo-ds-japan', 'NDS', 'Asonde Igo ga Tsuyoku Naru! - Ginsei Igo DS (Japan)', '2007', 'Board Game', 'SilverStar Japan', '1-2', 'Traditional', 'Strategic board gameplay with interactive tutorials.', 'Learn the fundamentals of Go and win matches.', 'Comprehensive Go (Igo) training game.', 'Asonde Igo ga Tsuyoku Naru! is the perfect entry point for Go on the NDS. Featuring the Ginsei engine, it offers step-by-step guidance for beginners to understand and master the ancient board game of territorial control.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asonde-shougi-ga-tsuyoku-naru!---ginsei-shougi-ds-japan', 'NDS', 'Asonde Shougi ga Tsuyoku Naru! - Ginsei Shougi DS (Japan)', '2007', 'Board Game', 'SilverStar Japan', '1-2', 'Traditional', 'Turn-based strategy on a traditional Japanese grid.', 'Learn Shougi rules and checkmate the opponent.', 'Traditional Japanese Chess trainer.', 'Step into the world of Japanese strategy with Asonde Shougi ga Tsuyoku Naru! This NDS title uses the Ginsei Shougi engine to provide a realistic playing experience along with educational tools to improve your tactical game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asphalt---urban-gt-europe-enfrdeesit', 'NDS', 'Asphalt - Urban GT (Europe) (En,Fr,De,Es,It)', '2005', 'Racing', 'Gameloft', '1-4', 'Arcade Racing', 'Arcade-style racing with licensed supercars and nitro boosts.', 'Win street races and evade the police in urban environments.', 'High-speed urban racing simulation.', 'Asphalt - Urban GT brings intense arcade racing to your handheld. Drive legendary cars like the Lamborghini and Audi through global cities, featuring 3D graphics and high-octane gameplay that defined early DS racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asphalt---urban-gt-japan', 'NDS', 'Asphalt - Urban GT (Japan)', '2005', 'Racing', 'Gameloft', '1-4', 'Arcade Racing', 'Arcade-style racing with licensed supercars and nitro boosts.', 'Win street races and evade the police in urban environments.', 'High-speed urban racing simulation.', 'Asphalt - Urban GT brings intense arcade racing to your handheld. Drive legendary cars like the Lamborghini and Audi through global cities, featuring 3D graphics and high-octane gameplay that defined early DS racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asphalt---urban-gt-usa-enfres', 'NDS', 'Asphalt - Urban GT (USA) (En,Fr,Es)', '2005', 'Racing', 'Gameloft', '1-4', 'Arcade Racing', 'Arcade-style racing with licensed supercars and nitro boosts.', 'Win street races and evade the police in urban environments.', 'High-speed urban racing simulation.', 'Asphalt - Urban GT brings intense arcade racing to your handheld. Drive legendary cars like the Lamborghini and Audi through global cities, featuring 3D graphics and high-octane gameplay that defined early DS racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asphalt---urban-gt-2-europe-enfrdeesit', 'NDS', 'Asphalt - Urban GT 2 (Europe) (En,Fr,De,Es,It)', '2007', 'Racing', 'Gameloft', '1-4', 'Arcade Racing', 'Enhanced arcade racing with more cars and licensed music.', 'Dominate the street racing circuit and unlock new upgrades.', 'Intense street racing sequel.', 'Asphalt - Urban GT 2 takes the racing experience further on NDS. Featuring a licensed soundtrack and an expanded roster of cars and motorcycles, it offers deep customization and thrilling police chases in multiple game modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asphalt---urban-gt-2-usa-enfres', 'NDS', 'Asphalt - Urban GT 2 (USA) (En,Fr,Es)', '2007', 'Racing', 'Gameloft', '1-4', 'Arcade Racing', 'Enhanced arcade racing with more cars and licensed music.', 'Dominate the street racing circuit and unlock new upgrades.', 'Intense street racing sequel.', 'Asphalt - Urban GT 2 takes the racing experience further on NDS. Featuring a licensed soundtrack and an expanded roster of cars and motorcycles, it offers deep customization and thrilling police chases in multiple game modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('assassins-creed---altairs-chronicles-europe-enfrdeesit', 'NDS', 'Assassin''s Creed - Altair''s Chronicles (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'Gameloft', '1', 'Action Adventure', '3D action-adventure with stealth and platforming elements.', 'Find the Chalice and stop a mysterious Templar plot.', 'Prequel adventure in the Assassin''s Creed world.', 'Assassin''s Creed: Altair''s Chronicles for NDS is a 3D cinematic experience. Use stealth, parkour, and a variety of weapons to navigate through ancient cities in a high-stakes mission that predates the original game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('assassins-creed---altairs-chronicles-usa-enfres', 'NDS', 'Assassin''s Creed - Altair''s Chronicles (USA) (En,Fr,Es)', '2008', 'Action', 'Gameloft', '1', 'Action Adventure', '3D action-adventure with stealth and platforming elements.', 'Find the Chalice and stop a mysterious Templar plot.', 'Prequel adventure in the Assassin''s Creed world.', 'Assassin''s Creed: Altair''s Chronicles for NDS is a 3D cinematic experience. Use stealth, parkour, and a variety of weapons to navigate through ancient cities in a high-stakes mission that predates the original game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('assassins-creed-ii---discovery-europe-enfrdeesitnlsvnoda-ndsi-enhanced', 'NDS', 'Assassin''s Creed II - Discovery (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da) (NDSi Enhanced)', '2009', 'Action', 'Gameloft', '1', 'Action Platformer', '2D side-scrolling parkour and stealth action.', 'Help Ezio Auditore stop a Templar conspiracy in Spain.', 'Fast-paced 2D stealth platformer.', 'Assassin''s Creed II - Discovery delivers high-speed parkour action. Navigate through 15th-century Spain, using Ezio''s signature hidden blades and agility to complete missions and rescue fellow assassins on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('assassins-creed-ii---discovery-usa-enfres-ndsi-enhanced', 'NDS', 'Assassin''s Creed II - Discovery (USA) (En,Fr,Es) (NDSi Enhanced)', '2009', 'Action', 'Gameloft', '1', 'Action Platformer', '2D side-scrolling parkour and stealth action.', 'Help Ezio Auditore stop a Templar conspiracy in Spain.', 'Fast-paced 2D stealth platformer.', 'Assassin''s Creed II - Discovery delivers high-speed parkour action. Navigate through 15th-century Spain, using Ezio''s signature hidden blades and agility to complete missions and rescue fellow assassins on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix---brain-trainer-europe-enfrdeesitnl', 'NDS', 'Asterix - Brain Trainer (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Educational', 'Shinen Multimedia', '1', 'Brain Training', 'Logic puzzles, math drills, and memory mini-games.', 'Train your brain alongside Asterix and Obelix.', 'Fun Gaul-themed brain training.', 'Asterix: Brain Trainer offers a series of mental challenges designed to keep your mind sharp. Enjoy various mini-games inspired by the classic comic books, covering memory, logic, and observation skills for all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix---these-romans-are-crazy!-europe-enfrdeitnl', 'NDS', 'Asterix - These Romans Are Crazy! (Europe) (En,Fr,De,It,Nl)', '2007', 'Action', 'Etranges Libellules', '1', 'Platformer', 'Strategy and management mini-games with comic book humor.', 'Defend the Gaulish village and humiliate the Romans.', 'Wacky strategy mini-game collection.', 'These Romans Are Crazy! brings the humor of Asterix to NDS. Engage in a variety of funny challenges and strategic tasks as you help the indomitable Gauls resist the Roman occupation in a lighthearted adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-&-obelix-xxl-2---mission-wifix-europe-enfrdeesitnl', 'NDS', 'Asterix & Obelix XXL 2 - Mission Wifix (Europe) (En,Fr,De,Es,It,Nl)', '2006', 'Action', 'Etranges Libellules', '1', 'Platformer', '3D action-platformer with combat and puzzle-solving.', 'Infiltrate Las Vegum and find the missing druids.', 'Parody-filled action adventure.', 'Asterix & Obelix XXL 2: Mission Wifix is a hilarious tribute to video game history. Battle through a Roman theme park, use powerful combos, and enjoy a story packed with references to other famous gaming icons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-at-the-olympic-games-europe-enfrdeesitnl', 'NDS', 'Asterix at the Olympic Games (Europe) (En,Fr,De,Es,It,Nl)', '2007', 'Action', 'Etranges Libellules', '1', 'Action Adventure', 'Sports mini-games based on Olympic disciplines.', 'Compete in various events to win the gold medal.', 'Classic sports competition with a Gaulish twist.', 'Join Asterix and his friends at the Olympic Games. This NDS title features a variety of touch-screen and microphone-based events, allowing you to compete for glory against the Roman Empire in athletic challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('astro-boy---the-video-game-europe-enfrdeesit', 'NDS', 'Astro Boy - The Video Game (Europe) (En,Fr,De,Es,It)', '2009', 'Action', 'High Voltage Software', '1', 'Action Adventure', 'Side-scrolling beat ''em up and shooter action.', 'Save Metro City from the evil President Stone.', 'High-flying robot action adventure.', 'Astro Boy: The Video Game puts you in control of the iconic robot hero. Use your arm cannon and jet-powered boots to battle enemies across 2D and 3D levels inspired by the animated feature film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('astro-boy---the-video-game-usa-enfrdeesit', 'NDS', 'Astro Boy - The Video Game (USA) (En,Fr,De,Es,It)', '2009', 'Action', 'High Voltage Software', '1', 'Action Adventure', 'Side-scrolling beat ''em up and shooter action.', 'Save Metro City from the evil President Stone.', 'High-flying robot action adventure.', 'Astro Boy: The Video Game puts you in control of the iconic robot hero. Use your arm cannon and jet-powered boots to battle enemies across 2D and 3D levels inspired by the animated feature film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('astro-invaders-usa-enfres', 'NDS', 'Astro Invaders (USA) (En,Fr,Es)', '2009', 'Action', 'PictureHouse Interactive', '1', 'Arcade Shooter', 'Fixed-shooter arcade gameplay inspired by classics.', 'Defend the planet from waves of invading alien forces.', 'Retro-style space shooting action.', 'Astro Invaders is a modern take on the classic arcade shooter. Test your reflexes as you blast through hordes of extraterrestrial enemies, aiming for high scores in this addictive and fast-paced NDS action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('astrology-europe-enfrdeesit', 'NDS', 'Astrology (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Mindscape', '1', 'Astrology', 'Personal horoscope and zodiac analysis software.', 'Discover your astrological profile and daily predictions.', 'A portable personal astrology guide.', 'Astrology for NDS offers a deep dive into the stars. Enter your birth details to receive personalized horoscopes, compatibility checks, and insights into your personality based on Western astrological traditions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('astrology-ds---the-stars-in-your-hands-usa-enfres', 'NDS', 'Astrology DS - The Stars in Your Hands (USA) (En,Fr,Es)', '2008', 'Simulation', 'Mindscape', '1', 'Astrology', 'Personal horoscope and zodiac analysis software.', 'Discover your astrological profile and daily predictions.', 'A portable personal astrology guide.', 'Astrology DS: The Stars in Your Hands provides a comprehensive look at your zodiac. Use the touch screen to navigate daily charts, learn about planet alignments, and discover what the future holds for you.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atama-de-do!-kotencotenco-japan', 'NDS', 'Atama de Do! Kotencotenco (Japan)', '2006', 'Puzzle', 'Success', '1', 'Casual Puzzle', 'Mini-game collection based on the anime series.', 'Complete various educational puzzles and logic tasks.', 'Fun anime-themed brain training for kids.', 'Atama de Do! Kotencotenco brings the colorful anime characters to NDS. Solve a variety of mini-games designed to stimulate the minds of younger players through logic, pattern recognition, and memory challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atama-no-kaiten-no-training---rubiks-cube-&-chou-yuumei-puzzle-tachi-japan', 'NDS', 'Atama no Kaiten no Training - Rubik''s Cube & Chou Yuumei Puzzle-tachi (Japan)', '2007', 'Puzzle', 'Nintendo', '1', 'Brain Training', 'Puzzle solving involving the Rubik''s Cube and other logic toys.', 'Master the Rubik''s Cube and solve world-famous puzzles.', 'The ultimate digital puzzle collection.', 'Atama no Kaiten no Training features a fully interactive 3D Rubik''s Cube. Learn solution techniques and challenge yourself with other legendary logic puzzles like Sudoku in this comprehensive brain-teasing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atama-o-kitaete-asobu-taisen-yajirushi-puzzle---puppynu-vector-one-japan', 'NDS', 'Atama o Kitaete Asobu Taisen Yajirushi Puzzle - Puppynu Vector One (Japan)', '2008', 'Puzzle', 'Success', '1', 'Logic Puzzle', 'Competitive puzzle gameplay using arrow-based mechanics.', 'Outsmart opponents by placing arrows to guide units.', 'Unique strategic arrow puzzle.', 'Puppynu Vector One offers a fresh take on the puzzle genre. Use the NDS touch screen to strategically place arrows on the board, outmaneuvering your rivals in a fast-paced battle of logic and direction.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atari-greatest-hits---volume-1-europe-enfrde', 'NDS', 'Atari Greatest Hits - Volume 1 (Europe) (En,Fr,De)', '2010', 'Compilation', 'Code Mystics', '1-4', 'Classic Arcade', 'Emulated arcade and console classics from the Atari library.', 'Relive gaming history and achieve high scores.', 'Collection of retro arcade hits.', 'Atari Greatest Hits Volume 1 brings the golden age of gaming to NDS. Play legends like Asteroids, Centipede, and Missile Command, complete with original artwork and historical trivia for retro enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atari-greatest-hits---volume-1-usa', 'NDS', 'Atari Greatest Hits - Volume 1 (USA)', '2010', 'Compilation', 'Code Mystics', '1-4', 'Classic Arcade', 'Emulated arcade and console classics from the Atari library.', 'Relive gaming history and achieve high scores.', 'Collection of retro arcade hits.', 'Atari Greatest Hits Volume 1 brings the golden age of gaming to NDS. Play legends like Asteroids, Centipede, and Missile Command, complete with original artwork and historical trivia for retro enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atari-greatest-hits---volume-2-usa', 'NDS', 'Atari Greatest Hits - Volume 2 (USA)', '2011', 'Compilation', 'Code Mystics', '1-4', 'Classic Arcade', 'Emulated arcade and console classics from the Atari library.', 'Relive gaming history and achieve high scores.', 'Second collection of retro arcade hits.', 'Atari Greatest Hits Volume 2 expands your portable library with more classics. Enjoy titles like Adventure and Warlords, featuring multiplayer support and a museum of Atari history on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atarimix---happy-10-games-japan', 'NDS', 'Atarimix - Happy 10 Games (Japan)', '2008', 'Compilation', 'Atari', '1-4', 'Casual', 'Mini-game collection featuring updated Atari classics.', 'Complete 10 different arcade-style challenges.', 'Modernized Atari mini-game pack.', 'Atarimix brings a fresh look to 10 beloved Atari games. Experience titles like Breakout and Tempest with updated graphics and touch-screen controls designed specifically for the Nintendo DS hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atelier-annie---alchemists-of-sera-island-usa', 'NDS', 'Atelier Annie - Alchemists of Sera Island (USA)', '2009', 'RPG', 'Gust', '1', 'JRPG', 'RPG with management and deep alchemy crafting systems.', 'Turn Sera Island into a successful resort through alchemy.', 'Addictive alchemy-based management RPG.', 'Atelier Annie: Alchemists of Sera Island combines the classic crafting of the Atelier series with resort management. Collect materials, synthesize items, and win contests to fund your island''s growth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atsumare!-power-pro-kun-no-ds-koushien-japan', 'NDS', 'Atsumare! Power Pro Kun no DS Koushien (Japan)', '2007', 'Sports', 'Konami', '1-4', 'Baseball', 'Sports simulation and school life management.', 'Lead your high school baseball team to the Koushien finals.', 'Baseball and school management simulation.', 'Power Pro Kun no DS Koushien offers a deep look at high school baseball. Manage your players'' training, balance school life, and participate in intense baseball matches to reach the national championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atsumare!-power-pro-kun-no-ds-koushien-japan-rev-1', 'NDS', 'Atsumare! Power Pro Kun no DS Koushien (Japan) (Rev 1)', '2007', 'Sports', 'Konami', '1-4', 'Baseball', 'Sports simulation and school life management.', 'Lead your high school baseball team to the Koushien finals.', 'Baseball and school management simulation.', 'Power Pro Kun no DS Koushien offers a deep look at high school baseball. Manage your players'' training, balance school life, and participate in intense baseball matches to reach the national championship.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atsumete!-kirby-japan', 'NDS', 'Atsumete! Kirby (Japan)', '2008', 'Action', 'HAL Laboratory', '1', 'Action Platformer', 'Controlling a swarm of Kirbys using the stylus for combat and puzzles.', 'Guide a group of up to 10 Kirbys to defeat Necrodeus.', 'A unique mass-control Kirby adventure.', 'Atsumete! Kirby (Kirby Mass Attack) brings a fresh mechanic to the series. Use the stylus to flick, swim, and command a horde of Kirbys to overwhelm enemies and solve environmental puzzles in this vibrant NDS platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atv-quad-frenzy-europe-enfrde', 'NDS', 'ATV Quad Frenzy (Europe) (En,Fr,De)', '2005', 'Racing', 'Team6 Game Studios', '1-4', 'Arcade Racing', 'Off-road racing with ATVs across various terrain types.', 'Win races and earn credits to upgrade your quad bike.', 'High-octane ATV racing simulation.', 'ATV Quad Frenzy delivers intense off-road action on the NDS. Race through diverse environments, master difficult jumps, and use your winnings to customize your vehicle in this fast-paced handheld racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atv-quad-frenzy-usa', 'NDS', 'ATV Quad Frenzy (USA)', '2005', 'Racing', 'Team6 Game Studios', '1-4', 'Arcade Racing', 'Off-road racing with ATVs across various terrain types.', 'Win races and earn credits to upgrade your quad bike.', 'High-octane ATV racing simulation.', 'ATV Quad Frenzy delivers intense off-road action on the NDS. Race through diverse environments, master difficult jumps, and use your winnings to customize your vehicle in this fast-paced handheld racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('au-pays-des-pooyoos---activites-deveil-france', 'NDS', 'Au Pays des PooYoos - Activites d''Eveil (France)', '2008', 'Educational', 'Mindscape', '1', 'Early Learning', 'Educational mini-games designed for very young children.', 'Complete simple shapes, colors, and music activities.', 'A poetic early-learning game for toddlers.', 'Au Pays des PooYoos is an adorable educational title for the NDS. It provides a safe, interactive environment where toddlers can learn basic concepts through gentle gameplay and charming characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('auto-escuela---aprueba-conmigo-spain', 'NDS', 'Auto Escuela - Aprueba Conmigo (Spain)', '2008', 'Educational', 'Proein Games', '1', 'Driving Education', 'Educational quizzes and simulation for driving theory.', 'Practice and pass the Spanish driving license exam.', 'Official Spanish driving theory trainer.', 'Auto Escuela - Aprueba Conmigo is a comprehensive study tool for the NDS. It features thousands of official questions and mock exams to help Spanish students prepare for their driver''s license test anywhere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('autoescuela-trainer-spain', 'NDS', 'Autoescuela Trainer (Spain)', '2009', 'Educational', 'Proein Games', '1', 'Driving Education', 'Educational quizzes and simulation for driving theory.', 'Master traffic rules and pass driving theory tests.', 'Driving school exam preparation guide.', 'Autoescuela Trainer turns your NDS into a portable classroom. Practice traffic signs, priority rules, and test your knowledge with realistic exam simulations designed to help you get your license on the first try.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('avalon-code-europe-enfrde', 'NDS', 'Avalon Code (Europe) (En,Fr,De)', '2008', 'RPG', 'Matrix Software', '1', 'Action RPG', 'Action-RPG where you edit world properties using a magical book.', 'Rewrite the world''s code to save it from destruction.', 'Innovative book-based action-RPG.', 'Avalon Code features the Book of Prophecy, allowing you to scan enemies and objects to change their attributes. This deep NDS RPG combines real-time combat with a unique "Code Flick" system to customize your adventure.');
