INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('avatar---the-last-airbender---into-the-inferno-usa', 'NDS', 'Avatar - The Last Airbender - Into the Inferno (USA)', '2008', 'Action', 'THQ Studio Australia', '1', 'Action Adventure', 'Action-adventure with elemental combat and puzzle solving.', 'Reach the Fire Nation and defeat the Fire Lord.', 'The final chapter of the Avatar trilogy.', 'Avatar - Into the Inferno on NDS focuses on the climactic events of Book 3. Use the touch screen to manipulate elements and guide Aang and his friends through intense battles to restore balance to the world.');
