INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('away---shuffle-dungeon-europe-enfrdeesit', 'NDS', 'Away - Shuffle Dungeon (Europe) (En,Fr,De,Es,It)', '2008', 'Action', 'Renekton', '1', 'Action RPG', 'Action-RPG featuring a shifting dungeon mechanic.', 'Explore dungeons that "shuffle" their layout in real-time.', 'A unique shifting-grid RPG adventure.', 'Away - Shuffle Dungeon features a dual-screen mechanic where the dungeon layout shifts between the top and bottom screens. Time your movements perfectly to avoid being trapped in this innovative NDS RPG.');
