INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('b-17---fortress-in-the-sky-europe-enfresit', 'NDS', 'B-17 - Fortress in the Sky (Europe) (En,Fr,Es,It)', '2007', 'Simulation', 'Magic Pockets', '1', 'Flight Simulation', 'Flight simulation and aerial combat set in WWII.', 'Complete bombing missions and defend your B-17 bomber.', 'Realistic WWII aerial combat sim.', 'B-17 - Fortress in the Sky puts you in control of a legendary bomber. Manage your crew, man the turrets, and navigate through enemy-filled skies to deliver your payload in this historical NDS simulation.');
