INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('b-sokal-syberia-usa-enfres', 'NDS', 'B. Sokal Syberia (USA) (En,Fr,Es)', '2002', 'Adventure', 'Microïds', '1', 'Point and Click', 'Point-and-click adventure with deep storytelling and puzzles.', 'Help Kate Walker uncover the mystery of the mammoths.', 'A classic and beautiful adventure journey.', 'Syberia on NDS brings Benoit Sokal''s masterpiece to the handheld. Explore steampunk environments, solve intricate mechanical puzzles, and experience a cinematic story across a mysterious, frozen landscape.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baby-life-europe-enfrdeesitnl', 'NDS', 'Baby Life (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Simulation', 'DTP Entertainment', '1', 'Life Simulation', 'Life simulation focused on caring for and raising infants.', 'Care for babies and help them hit development milestones.', 'A detailed baby-raising simulator.', 'Baby Life lets you experience the joys and challenges of parenthood. From feeding and playing to dressing and teaching, manage every aspect of your virtual baby''s growth in this heartwarming NDS title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baby-luigi', 'NDS', 'Baby Luigi', '2006', 'Platformer', 'Nintendo', '1', 'Action Platformer', 'Character-based mini-games and educational activities.', 'Complete challenges featuring the younger version of Luigi.', 'A fun mini-game pack with Baby Luigi.', 'Baby Luigi features various touch-screen challenges designed for younger players. Explore the mushroom kingdom from a toddler''s perspective while completing puzzles and simple arcade-style tasks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baby-mario', 'NDS', 'Baby Mario', '2006', 'Platformer', 'Nintendo', '1', 'Action Platformer', 'Character-based mini-games and educational activities.', 'Complete challenges featuring the younger version of Mario.', 'A fun mini-game pack with Baby Mario.', 'Baby Mario brings the iconic hero''s younger self to the NDS. Participate in colorful activities, learn basic coordination, and enjoy the whimsical world of Nintendo through child-friendly mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baby-pals-europe-enfrdeesit', 'NDS', 'Baby Pals (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Studio Animal', '1', 'Pet Simulation', 'Virtual pet simulation focused on baby care using the stylus.', 'Feed, bathe, and play with your baby to keep them happy.', 'A heartwarming baby care simulator.', 'Baby Pals on NDS lets you experience the joys of parenting. Use the touch screen to interact with adorable infants, teaching them to crawl and speak while managing their daily needs in this charming simulation.');
