INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baby-wild-katzen-germany', 'NDS', 'Baby Wild Katzen (Germany)', '2009', 'Simulation', 'Tivola', '1', 'Pet Simulation', 'Simulation and care of wild feline cubs in a sanctuary.', 'Raise and protect big cat cubs until they are self-sufficient.', 'Wild cat cub raising simulation.', 'Baby Wild Katzen allows you to care for lions, tigers, and leopards. Learn about wildlife conservation while feeding and playing with these majestic predators in a safe, digital environment on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('babysitting-mania-europe-enfrdeesitnl', 'NDS', 'Babysitting Mania (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Simulation', 'Lexis Numérique', '1', 'Time Management', 'Time management and cleaning mini-games.', 'Complete household chores and manage unruly kids before time runs out.', 'Fast-paced babysitting simulation.', 'Babysitting Mania challenges your multitasking skills. Clean the house and keep the kids under control across dozens of levels to earn the title of ultimate babysitter in this addictive NDS title.');
