INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bachelor-the---the-videogame-usa-enfres', 'NDS', 'Bachelor, The - The Videogame (USA) (En,Fr,Es)', '2010', 'Simulation', 'Semicom', '1', 'Reality Show', 'Adventure and social simulation based on the dating show.', 'Compete in challenges and build relationships to find true love.', 'Official dating reality show game.', 'The Bachelor: The Videogame brings the drama of the TV show to NDS. Participate in group dates, navigate social interactions, and hope to receive the final rose in this romantic competition sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('back-at-the-barnyard---barnyard-games-europe', 'NDS', 'Back at the Barnyard - Barnyard Games (Europe)', '2007', 'Party', 'THQ', '1-4', 'Minigames', 'Mini-game collection featuring farm animals from the show.', 'Win various farm-themed sports and comedy events.', 'Wacky farm-based mini-game fun.', 'Join Otis and the gang in Back at the Barnyard. This NDS title features a variety of humorous challenges and arcade-style games inspired by the hit Nickelodeon animated series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('back-at-the-barnyard---slop-bucket-games-usa', 'NDS', 'Back at the Barnyard - Slop Bucket Games (USA)', '2007', 'Party', 'THQ', '1-4', 'Minigames', 'Mini-game collection featuring farm animals from the show.', 'Win various farm-themed sports and comedy events.', 'Wacky farm-based mini-game fun.', 'Join Otis and the gang in Back at the Barnyard. This NDS title features a variety of humorous challenges and arcade-style games inspired by the hit Nickelodeon animated series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backgammon-germany', 'NDS', 'Backgammon (Germany)', '2007', 'Board Game', 'Koch Media', '1-2', 'Traditional', 'Classic board game simulation with touch screen controls.', 'Move all your checkers into your home board and bear them off.', 'Digital version of the classic board game.', 'Backgammon for NDS provides a portable way to play the ancient strategy game. Features adjustable AI difficulty levels and clean visuals, making it perfect for both casual and serious players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-baseball-09-usa', 'NDS', 'Backyard Baseball ''09 (USA)', '2009', 'Sports', 'Humongous Entertainment', '1-2', 'Baseball', 'Arcade-style baseball with power-ups and child characters.', 'Win the World Series with a team of neighborhood kids.', 'Kid-friendly arcade baseball action.', 'Backyard Baseball ''09 features the Backyard Kids and pro players as children. Use the stylus to pitch, hit, and activate "Power-Ups" in this accessible and fun sports title for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-baseball-10-usa', 'NDS', 'Backyard Baseball ''10 (USA)', '2010', 'Sports', 'Humongous Entertainment', '1-2', 'Baseball', 'Arcade-style baseball with power-ups and child characters.', 'Win the World Series with a team of neighborhood kids.', 'Kid-friendly arcade baseball action.', 'Backyard Baseball ''10 brings updated rosters and new fields to the NDS. Enjoy a deep season mode and fast-paced arcade gameplay that makes baseball fun for younger audiences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-basketball-usa', 'NDS', 'Backyard Basketball (USA)', '2007', 'Sports', 'Humongous Entertainment', '1-2', 'Basketball', 'Arcade-style basketball with 3-on-3 gameplay.', 'Outscore the opposing team using special moves and dunks.', 'Fun neighborhood basketball action.', 'Backyard Basketball offers a stylized take on hoops. Build your dream team of kids and pro stars to dominate the court with unique power-plays and intuitive touch-screen controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-football-09-usa', 'NDS', 'Backyard Football ''09 (USA)', '2009', 'Sports', 'Humongous Entertainment', '1-2', 'Football', 'Arcade-style American football with strategy and power-ups.', 'Score touchdowns and win the Backyard Bowl.', 'Accessible arcade football for kids.', 'Backyard Football ''09 delivers hard-hitting action in a kid-friendly package. Manage your plays and utilize special power-ups to lead your team to victory on the NDS gridiron.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-football-usa', 'NDS', 'Backyard Football (USA)', '2007', 'Sports', 'Humongous Entertainment', '1-2', 'Football', 'Arcade-style American football with strategy and power-ups.', 'Score touchdowns and win the Backyard Bowl.', 'Accessible arcade football for kids.', 'Backyard Football on NDS simplifies the sport for maximum fun. Pick your favorite players, choose your plays, and experience high-scoring games with the Backyard Kids.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-hockey-usa', 'NDS', 'Backyard Hockey (USA)', '2008', 'Sports', 'Humongous Entertainment', '1-2', 'Hockey', 'Arcade-style ice hockey with fast-paced skating and shooting.', 'Score goals and win the championship on the ice.', 'Fast-paced kid-friendly hockey.', 'Backyard Hockey brings the excitement of the NHL to a neighborhood level. Features 3-on-3 action, customizable teams, and the signature Backyard Sports humor and power-ups.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-sports---rookie-rush-usa', 'NDS', 'Backyard Sports - Rookie Rush (USA)', '2009', 'Sports', 'Humongous Entertainment', '1-4', 'Sports Compilation', 'Multi-sport arcade action with a focus on speed and fun.', 'Compete in various sports and unlock new rookie players.', 'Fast-paced sports mini-game collection.', 'Backyard Sports: Rookie Rush features a variety of athletic challenges. Perfect for quick sessions, this NDS title offers simplified controls and high-energy gameplay across multiple popular sports.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-sports---sandlot-sluggers-usa', 'NDS', 'Backyard Sports - Sandlot Sluggers (USA)', '2010', 'Sports', 'Humongous Entertainment', '1-2', 'Baseball', 'Arcade baseball focusing on home runs and street play.', 'Hit home runs and win games in neighborhood sandlots.', 'Casual arcade baseball adventure.', 'Backyard Sports: Sandlot Sluggers emphasizes the fun of neighborhood play. Master the timing of your swings to hit massive home runs and lead your team to victory in this colorful NDS title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyardigans-the-europe', 'NDS', 'Backyardigans, The (Europe)', '2009', 'Adventure', 'Nickelodeon', '1', 'Platformer', 'Adventure and mini-games based on the musical TV show.', 'Go on imaginative journeys and solve puzzles with music.', 'Musical adventure for preschoolers.', 'The Backyardigans for NDS lets young fans join Pablo, Tyrone, and friends on their backyard adventures. Features educational mini-games and catchy songs that follow the spirit of the show.');
