INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bae-yong-joon-to-manabu-kankokugo-ds-japan', 'NDS', 'Bae Yong-Joon to Manabu Kankokugo DS (Japan)', '2009', 'Educational', '4mm Games', '1', 'Language Learning', 'Educational language learning with celebrity guidance.', 'Learn Korean vocabulary and grammar with actor Bae Yong-Joon.', 'Interactive Korean language trainer.', 'Bae Yong-Joon to Manabu Kankokugo DS uses the fame of the "Winter Sonata" star to teach Korean. It features structured lessons, voice samples, and writing practice using the NDS stylus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baerenbabys-europe-enfrdeesit', 'NDS', 'Baerenbabys (Europe) (En,Fr,De,Es,It)', '2008', 'Simulation', 'Tivola', '1', 'Pet Simulation', 'Virtual pet simulation focused on raising bear cubs.', 'Care for different bear species and watch them grow.', 'Cute bear cub raising simulation.', 'Baerenbabys allows you to raise polar bears, pandas, and more. Use the touch screen to feed, groom, and play with your bear cubs in this gentle and educational animal care game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bakugan---battle-brawlers---battle-trainer-europe-enfrdeesitnlsv', 'NDS', 'Bakugan - Battle Brawlers - Battle Trainer (Europe) (En,Fr,De,Es,It,Nl,Sv)', '2010', 'Action', 'Hudson Soft', '1-2', 'Training', 'Monster-collecting and training mini-games.', 'Train your Bakugan creatures to increase their battle stats.', 'Training-focused Bakugan simulation.', 'Bakugan: Battle Trainer is designed to hone your skills for the main game. Engage in various mini-games to improve your Bakugan''s abilities and learn the deep mechanics of the Battle Brawlers universe.');
