INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bakumatsu-renka-shinsengumi-ds-japan', 'NDS', 'Bakumatsu Renka Shinsengumi DS (Japan)', '2008', 'Adventure', 'D3 Publisher', '1', 'Historical Visual Novel', 'Otome visual novel set in historical Japan.', 'Navigate romantic interests within the famous Shinsengumi.', 'Historical romance visual novel.', 'Bakumatsu Renka Shinsengumi DS is a remastered classic. Experience the drama of the Bakumatsu period as you form bonds with legendary samurai in this deep, choice-driven narrative for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bakushow---challenge-your-friends!-europe-enfrdeesit', 'NDS', 'Bakushow - Challenge Your Friends! (Europe) (En,Fr,De,Es,It)', '2009', 'Party', 'Magic Pockets', '1-4', 'Game Show', 'Creative drawing and multiplayer party game.', 'Win rounds by drawing the funniest or most accurate responses.', 'Hilarious multiplayer drawing game.', 'Bakushow is the ultimate NDS party game. Challenge up to 7 friends to a battle of wit and drawing, where players vote on the best answers to wacky prompts in a fast-paced competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bakusou-dekotora-densetsu-black-japan', 'NDS', 'Bakusou Dekotora Densetsu Black (Japan)', '2008', 'Racing', 'Spike', '1-2', 'Arcade Racing', 'Truck driving and customization simulation.', 'Win races to earn parts and build the ultimate "Dekotora" truck.', 'Unique Japanese truck racing culture game.', 'Bakusou Dekotora Densetsu Black celebrates the world of decorated trucks. Customize your rig with lights and art, then compete in high-stakes highway races across Japan in this atmospheric NDS title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ballerina-europe-enfrdeesitnl', 'NDS', 'Ballerina (Europe) (En,Fr,De,Es,It,Nl)', '2009', 'Simulation', 'DTG Studios', '1', 'Dance', 'Rhythm and dance simulation for aspiring ballerinas.', 'Practice ballet moves and perform in world-class recitals.', 'Elegant ballet and rhythm game.', 'Ballerina for NDS lets you live the dream of a professional dancer. Use the stylus to follow rhythm patterns, master difficult choreography, and rise from a student to a prima ballerina.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('balloon-pop-usa', 'NDS', 'Balloon Pop (USA)', '2009', 'Puzzle', 'Sanuk Games', '1', 'Casual Puzzle', 'Puzzle-solving with matching and chain-reaction mechanics.', 'Pop colorful balloons by creating groups of three or more.', 'A bright and addictive puzzle game.', 'Balloon Pop for NDS offers a cheerful take on the match-3 genre. Use the stylus to strategically clear balloons, trigger explosive combos, and solve diverse puzzle boards across multiple game modes for all ages.');
