INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie---groom-and-glam-pups-europe-enfrdeesitnl', 'NDS', 'Barbie - Groom and Glam Pups (Europe) (En,Fr,De,Es,It,Nl)', '2010', 'Simulation', 'EA Bright Light', '1', 'Pet Care', 'Pet care and beauty simulation for dogs.', 'Groom, train, and dress up pups for the ultimate dog show.', 'A stylish dog care and glamour game.', 'Barbie: Groom and Glam Pups lets you pamper a variety of adorable breeds. Use the touch screen to brush, bathe, and train your pets to perform tricks and win prestigious beauty competitions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-and-the-three-musketeers-europe-deit', 'NDS', 'Barbie and the Three Musketeers (Europe) (De,It)', '2009', 'Adventure', 'EA Bright Light', '1', 'Story Adventure', 'Side-scrolling platformer with puzzles and combat.', 'Help Barbie and her friends save the King from a coup.', 'Adventure based on the Three Musketeers.', 'Join Corinne and her fellow musketeers in this NDS adventure. Use unique skills like ribbon-whipping and agility to overcome obstacles and complete missions in a story of teamwork and bravery.');
