INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-horse-adventures---riding-camp-europe-enfrdeesitnl', 'NDS', 'Barbie Horse Adventures - Riding Camp (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Simulation', 'Kuju Entertainment', '1', 'Horse Riding', 'Open-world horse riding and stable management.', 'Train horses and solve mysteries at the riding camp.', 'Equestrian adventure and horse care.', 'Barbie Horse Adventures: Riding Camp offers a mix of horse training and exploration. Groom your horses, practice jumping, and complete various quests around the island in this comprehensive horse sim for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-horse-adventures---riding-camp-usa-enfr', 'NDS', 'Barbie Horse Adventures - Riding Camp (USA) (En,Fr)', '2008', 'Simulation', 'Kuju Entertainment', '1', 'Horse Riding', 'Open-world horse riding and stable management.', 'Train horses and solve mysteries at the riding camp.', 'Equestrian adventure and horse care.', 'Barbie Horse Adventures: Riding Camp offers a mix of horse training and exploration. Groom your horses, practice jumping, and complete various quests around the island in this comprehensive horse sim for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-in-the-12-dancing-princesses-europe-enfrdeesit', 'NDS', 'Barbie in the 12 Dancing Princesses (Europe) (En,Fr,De,Es,It)', '2006', 'Adventure', 'EA Bright Light', '1', 'Dance Adventure', 'Platforming and rhythm-based dancing mini-games.', 'Save the King and find the 12 dancing sisters.', 'Magical dance and platforming adventure.', 'Based on the film, 12 Dancing Princesses features Genevieve on a quest. Master dance moves to solve puzzles and navigate enchanted environments in this graceful and fun NDS title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-in-the-12-dancing-princesses-usa', 'NDS', 'Barbie in the 12 Dancing Princesses (USA)', '2006', 'Adventure', 'EA Bright Light', '1', 'Dance Adventure', 'Platforming and rhythm-based dancing mini-games.', 'Save the King and find the 12 dancing sisters.', 'Magical dance and platforming adventure.', 'Based on the film, 12 Dancing Princesses features Genevieve on a quest. Master dance moves to solve puzzles and navigate enchanted environments in this graceful and fun NDS title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barnyard---verrueckte-bauernhof-spiele-germany', 'NDS', 'Barnyard - Verrueckte Bauernhof-Spiele (Germany)', '2007', 'Party', 'THQ', '1-4', 'Minigames', 'Mini-game collection featuring farm animals from the show.', 'Win various farm-themed sports and comedy events.', 'Wacky farm-based mini-game fun.', 'Barnyard Games for NDS brings the humor of the Nickelodeon film to your handheld. Participate in golf, racing, and "slop bucket" challenges with Otis and the rest of the crazy animal cast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barnyard-blast---swine-of-the-night-europe-enfrdeesitpt', 'NDS', 'Barnyard Blast - Swine of the Night (Europe) (En,Fr,De,Es,It,Pt)', '2008', 'Action', 'Blue Tongue Entertainment', '1', 'Arcade Shooter', '2D action-platformer with a gothic, spooky theme.', 'Fight through hordes of monsters to defeat the Dark Lord.', 'A "Castlevania" style pig-themed adventure.', 'Barnyard Blast: Swine of the Night is a humorous parody of classic horror games. Play as Robert Belmont (a pig) and use whips and guns to battle skeletons and ghouls in this challenging NDS action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barnyard-blast---swine-of-the-night-usa-enfrespt', 'NDS', 'Barnyard Blast - Swine of the Night (USA) (En,Fr,Es,Pt)', '2008', 'Action', 'Blue Tongue Entertainment', '1', 'Arcade Shooter', '2D action-platformer with a gothic, spooky theme.', 'Fight through hordes of monsters to defeat the Dark Lord.', 'A "Castlevania" style pig-themed adventure.', 'Barnyard Blast: Swine of the Night is a humorous parody of classic horror games. Play as Robert Belmont (a pig) and use whips and guns to battle skeletons and ghouls in this challenging NDS action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bartender-ds-japan', 'NDS', 'Bartender DS (Japan)', '2007', 'Simulation', 'Success', '1', 'Job Simulation', 'Drink mixing and bar management simulation.', 'Mix the perfect cocktails to satisfy diverse customers.', 'An educational and fun mixology sim.', 'Bartender DS teaches you the art of cocktail making. Use the touch screen to pour, shake, and stir famous drinks while learning about the history and tools of the bartending trade in this unique title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bastian-sick-der-dativ-ist-dem-genitiv-sein-tod-germany', 'NDS', 'Bastian Sick Der Dativ Ist dem Genitiv Sein Tod (Germany)', '2009', 'Educational', 'Brainpool', '1', 'Language Learning', 'Language and grammar puzzles based on the best-selling book.', 'Improve your German grammar through engaging mini-games.', 'A fun German language and logic trainer.', 'Bastian Sick: Der Dativ ist dem Genitiv sein Tod challenges your knowledge of the German language. Solve clever linguistic puzzles and quizzes designed to sharpen your grammar and vocabulary skills on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman---the-brave-and-the-bold---the-videogame-europe-enfrdeesitnl', 'NDS', 'Batman - The Brave and the Bold - The Videogame (Europe) (En,Fr,De,Es,It,Nl)', '2010', 'Action', 'WayForward', '1', 'Action Platformer', '2D side-scrolling beat ''em up with superhero powers.', 'Team up with other DC heroes to stop villainous plots.', 'Classic superhero action-platforming.', 'Batman: The Brave and the Bold features fast-paced combat and platforming. Summon allies like Blue Beetle and Guy Gardner to unleash powerful combos and save the world in this stylish NDS adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman---the-brave-and-the-bold---the-videogame-usa-enfres', 'NDS', 'Batman - The Brave and the Bold - The Videogame (USA) (En,Fr,Es)', '2010', 'Action', 'WayForward', '1', 'Action Platformer', '2D side-scrolling beat ''em up with superhero powers.', 'Team up with other DC heroes to stop villainous plots.', 'Classic superhero action-platforming.', 'Batman: The Brave and the Bold features fast-paced combat and platforming. Summon allies like Blue Beetle and Guy Gardner to unleash powerful combos and save the world in this stylish NDS adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-of-giants---dinosaurs-usa-enfres', 'NDS', 'Battle of Giants - Dinosaurs (USA) (En,Fr,Es)', '2008', 'Simulation', 'Future Games of London', '1', 'Creature Combat', 'Arena-based combat and dinosaur customization.', 'Fight and evolve your dinosaur to become the ruler of the prehistoric world.', 'Primitive dinosaur duels and exploration.', 'Battle of Giants: Dinosaurs lets you create and customize your own prehistoric beast. Explore diverse territories and engage in strategic, gesture-based combat on the NDS touch screen to defeat rival giants.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-of-giants---dragons-usa-enfres-rev-1', 'NDS', 'Battle of Giants - Dragons (USA) (En,Fr,Es) (Rev 1)', '2009', 'Simulation', 'Future Games of London', '1', 'Creature Combat', 'Action-adventure with dragon-based flight and combat.', 'Defeat the dark dragon and restore peace to the floating islands.', 'Epic dragon battles and customization.', 'In Battle of Giants: Dragons, you control a powerful mythical beast. Tailor your dragon''s appearance and abilities, then engage in elemental battles and explore a world of floating islands in this immersive NDS RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-of-giants---mutant-insects-usa-enfres', 'NDS', 'Battle of Giants - Mutant Insects (USA) (En,Fr,Es)', '2010', 'Simulation', 'Future Games of London', '1', 'Creature Combat', 'Tactical combat featuring giant mutated insects.', 'Survive a post-apocalyptic world by evolving your insect warrior.', 'Mutant bug brawling and exploration.', 'Battle of Giants: Mutant Insects brings giant creepy-crawlies to life. Customize your insect with lethal mutations and use the NDS stylus to perform specialized attacks in a struggle for survival across a wasteland.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-spirits-digital-starter-japan', 'NDS', 'Battle Spirits Digital Starter (Japan)', '2009', 'Card', 'Game Studio', '1', 'Trading Card', 'Strategic card battle gameplay based on the anime.', 'Collect rare cards and win the Battle Spirits tournament.', 'Official card-battle RPG for NDS.', 'Battle Spirits Digital Starter is the ultimate portable companion for fans of the trading card game. Build a powerful deck, master the "Core" system, and duel against challenging AI opponents in a deep story mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battles-of-prince-of-persia-europe-enfrdeesitnl', 'NDS', 'Battles of Prince of Persia (Europe) (En,Fr,De,Es,It,Nl)', '2010', 'Action', 'Ubisoft Montreal', '1', 'Tactical Strategy', 'Turn-based tactical strategy with card-based mechanics.', 'Lead armies into battle and uncover the truth behind the Prince''s curse.', 'Tactical card-strategy Prince of Persia spin-off.', 'Battles of Prince of Persia bridges the gap between Sands of Time and Warrior Within. Manage units on a grid and use collectible cards to influence the outcome of large-scale military engagements on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battles-of-prince-of-persia-usa-enfrdeesitnl', 'NDS', 'Battles of Prince of Persia (USA) (En,Fr,De,Es,It,Nl)', '2010', 'Action', 'Ubisoft Montreal', '1', 'Tactical Strategy', 'Turn-based tactical strategy with card-based mechanics.', 'Lead armies into battle and uncover the truth behind the Prince''s curse.', 'Tactical card-strategy Prince of Persia spin-off.', 'Battles of Prince of Persia bridges the gap between Sands of Time and Warrior Within. Manage units on a grid and use collectible cards to influence the outcome of large-scale military engagements on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bauernhof-der-germany', 'NDS', 'Bauernhof, Der (Germany)', '2008', 'Simulation', 'Independent Arts', '1', 'Farming', 'Farm life simulation and resource management.', 'Build a successful farm by raising livestock and harvesting crops.', 'A charming farm management simulator.', 'Der Bauernhof (The Farm) invites you to experience rural life. Manage your time and finances, care for various farm animals, and expand your land in this relaxing and educational life simulation for NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beach-de-reach!-ds-japan', 'NDS', 'Beach de Reach! DS (Japan)', '2007', 'Action', 'Jupiter', '1', 'Arcade Action', 'Beach-themed Mahjong and mini-games.', 'Win Mahjong matches to enjoy a tropical vacation.', 'Tropical Japanese Mahjong simulation.', 'Beach de Reach! DS combines traditional Japanese Mahjong with a sunny beach atmosphere. Compete against various opponents and unlock summer-themed items in this lighthearted board game experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beat-city-europe-endeesit', 'NDS', 'Beat City (Europe) (En,De,Es,It)', '2009', 'Action', 'Ubisoft', '1', 'Rhythm Action', 'Rhythm-based puzzle and action gameplay.', 'Restore music and life to a city by tapping to the beat.', 'A quirky and vibrant rhythm adventure.', 'Beat City features a unique "one-touch" rhythm system. Help the city''s residents find their groove and defeat the silence-loving "Cacophony" in this colorful and musically-driven NDS challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beat-city-usa', 'NDS', 'Beat City (USA)', '2009', 'Action', 'Ubisoft', '1', 'Rhythm Action', 'Rhythm-based puzzle and action gameplay.', 'Restore music and life to a city by tapping to the beat.', 'A quirky and vibrant rhythm adventure.', 'Beat City features a unique "one-touch" rhythm system. Help the city''s residents find their groove and defeat the silence-loving "Cacophony" in this colorful and musically-driven NDS challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beat-the-intro-europe', 'NDS', 'Beat the Intro (Europe)', '2009', 'Music', 'Sanuk Games', '1', 'Rhythm', 'Music trivia and intro-guessing challenges.', 'Identify famous songs as quickly as possible to win.', 'The ultimate music intro quiz game.', 'Beat the Intro tests your musical knowledge. Listen to the opening seconds of hundreds of hit songs across various genres and prove you''re the ultimate music buff in this fast-paced NDS party game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beauty-salon-europe-enfrdeesit', 'NDS', 'Beauty Salon (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Creat Studios', '1', 'Casual Management', 'Salon management and beauty-themed mini-games.', 'Run a successful salon by providing perfect hair and makeup.', 'Fashion-forward beauty salon simulation.', 'Beauty Salon puts you in charge of a high-end makeover studio. Use the NDS stylus to cut hair, apply makeup, and choose outfits for your clients to become the most famous stylist in the city.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bee-game-the-usa', 'NDS', 'Bee Game, The (USA)', '2007', 'Puzzle', 'Sanuk Games', '1', 'Casual Puzzle', 'Side-scrolling adventure featuring honeybee mechanics.', 'Help the bees collect pollen and protect their hive.', 'A nature-themed adventure for kids.', 'The Bee Game takes players into the tiny world of bees. Navigate through gardens, avoid predators, and complete tasks to ensure the survival of your colony in this charming and educational NDS title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bee-movie---das-game-germany', 'NDS', 'Bee Movie - Das Game (Germany)', '2007', 'Action', 'Vicarious Visions', '1', 'Action Adventure', 'Action-adventure with flight and racing segments.', 'Help Barry B. Benson navigate the human world and save the honey.', 'Official movie-based action adventure.', 'Bee Movie Game lets you experience the life of Barry outside the hive. Fly through New York City, engage in high-speed chases, and solve puzzles in this fun adaptation of the DreamWorks animated hit.');
