INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bejeweled-3-europe-enfrde', 'NDS', 'Bejeweled 3 (Europe) (En,Fr,De)', '2010', 'Puzzle', 'PopCap Games', '1', 'Casual Puzzle', 'Classic match-3 puzzle gameplay with updated visuals.', 'Match gems to clear the board and reach high scores.', 'The definitive match-3 puzzle experience.', 'Bejeweled 3 for NDS brings the legendary puzzle series to the handheld. Featuring multiple game modes like Zen and Lightning, it offers addictive gameplay and stunning effects for puzzle fans of all levels.');
