INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('betty-boops-double-shift-europe-enfrdeesit', 'NDS', 'Betty Boop''s Double Shift (Europe) (En,Fr,De,Es,It)', '2011', 'Puzzle', 'WayForward', '1', 'Time Management', 'Time management and service simulation.', 'Manage a diner and a jazz club simultaneously to earn money.', 'Double-duty restaurant and club management.', 'Help the iconic Betty Boop manage her busy life in Betty Boop''s Double Shift. Balance serving customers in the diner with performing in a jazz club, using the stylus to keep everyone happy and maximize your tips.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('betty-boops-double-shift-usa', 'NDS', 'Betty Boop''s Double Shift (USA)', '2011', 'Puzzle', 'WayForward', '1', 'Time Management', 'Time management and service simulation.', 'Manage a diner and a jazz club simultaneously to earn money.', 'Double-duty restaurant and club management.', 'Help the iconic Betty Boop manage her busy life in Betty Boop''s Double Shift. Balance serving customers in the diner with performing in a jazz club, using the stylus to keep everyone happy and maximize your tips.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beyblade-metal-fusion---cyber-pegasus-europe', 'NDS', 'Beyblade Metal Fusion - Cyber Pegasus (Europe)', '2010', 'Action', 'Konami', '1', 'Action Fighting', 'Spinning top combat with customization and strategy.', 'Defeat rivals in the stadium to become the ultimate Blader.', 'High-intensity Beyblade battling action.', 'Experience the thrill of Metal Fusion on NDS. Customize your Beyblade with different parts, master the spirit gauge, and engage in tactical top-spinning battles against characters from the hit anime series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beyblade-metal-fusion-usa-enfres', 'NDS', 'Beyblade Metal Fusion (USA) (En,Fr,Es)', '2009', 'Action', 'Konami', '1', 'Action Fighting', 'Spinning top combat with customization and strategy.', 'Defeat rivals in the stadium to become the ultimate Blader.', 'High-intensity Beyblade battling action.', 'Experience the thrill of Metal Fusion on NDS. Customize your Beyblade with different parts, master the spirit gauge, and engage in tactical top-spinning battles against characters from the hit anime series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bff-tv-europe-enfrdeesit', 'NDS', 'BFF TV (Europe) (En,Fr,De,Es,It)', '2009', 'Simulation', 'Independent Arts', '1', 'Life Simulation', 'Social simulation and fashion-based mini-games.', 'Create a TV show and become a famous social media star.', 'Teen-focused social and fashion sim.', 'In BFF TV, you get to produce your own show. Design outfits, manage social interactions, and complete various mini-games to boost your popularity and become the trendiest star on the airwaves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bibi-&-tina---das-grosse-unwetter-germany', 'NDS', 'Bibi & Tina - Das Grosse Unwetter (Germany)', '2009', 'Adventure', 'Independent Arts', '1', 'Kids Adventure', 'Adventure and horse riding simulation.', 'Save the Martinshof farm from a devastating storm.', 'Horseback adventure based on the German series.', 'Join Bibi and Tina in this atmospheric adventure. Solve puzzles, care for your horses, and ride through the countryside to prevent disaster after a massive storm hits the farm.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bibi-&-tina---die-grosse-schnitzeljagd-europe-enfrde', 'NDS', 'Bibi & Tina - Die Grosse Schnitzeljagd (Europe) (En,Fr,De)', '2009', 'Adventure', 'Independent Arts', '1', 'Kids Adventure', 'Adventure and horse riding simulation.', 'Compete in a scavenger hunt and solve local mysteries.', 'Equestrian exploration and puzzle solving.', 'Participate in the Great Scavenger Hunt with Bibi and Tina. This NDS title combines horse racing, grooming, and detective work as you explore the world of the famous German franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bibi-blocksberg---das-gestohlene-hexbuch-germany', 'NDS', 'Bibi Blocksberg - Das Gestohlene Hexbuch (Germany)', '2008', 'Adventure', 'Independent Arts', '1', 'Kids Adventure', 'Adventure and magic-based puzzle solving.', 'Recover the stolen Book of Spells and stop the chaos.', 'A magical mystery adventure for kids.', 'Use Bibi’s witchcraft to solve the mystery of the missing book. Navigate through Neustadt, cast spells with the stylus, and complete magical mini-games in this charming German adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bibi-blocksberg---neustadt-im-hex-chaos-germany', 'NDS', 'Bibi Blocksberg - Neustadt im Hex-Chaos (Germany)', '2010', 'Adventure', 'Independent Arts', '1', 'Kids Adventure', 'Adventure and magic-based puzzle solving.', 'Restore order to Neustadt using witchcraft and logic.', 'Witch-themed adventure and mini-games.', 'Chaos has taken over Neustadt! Help Bibi Blocksberg use her magical powers to fix the town''s problems, solve puzzles, and fly on her broomstick in this fun NDS title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bibliothek-der-klassischen-buecher-germany', 'NDS', 'Bibliothek der Klassischen Buecher (Germany)', '2009', 'Educational', 'Independent Arts', '1', 'Reading Educational', 'Digital e-book reader and literary reference.', 'Read and organize a library of classic German literature.', 'A portable library of classic books.', 'Bibliothek der Klassischen Buecher turns your NDS into an e-reader. Access dozens of legendary German literary works, complete with bookmarks and adjustable text for a comfortable reading experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('biene-maja-die---klatschmohnwiese-in-gefahr-germany', 'NDS', 'Biene Maja, Die - Klatschmohnwiese in Gefahr (Germany)', '2010', 'Adventure', 'Independent Arts', '1', 'Kids Adventure', '2D platforming and nature-themed mini-games.', 'Save the Poppy Meadow from an environmental threat.', 'A gentle nature adventure for younger players.', 'Join Maya the Bee in a quest to protect her home. Fly through vibrant levels, interact with insect friends, and solve simple puzzles designed to teach children about nature and teamwork.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bienvenue-chez-les-chtis---le-jeu-france', 'NDS', 'Bienvenue Chez les Ch''tis - Le Jeu (France)', '2008', 'Party', 'Anuman Interactive', '1', 'Party Game', 'Mini-game collection based on the French comedy film.', 'Complete various cultural and wacky Northern French tasks.', 'Humorous mini-games based on the hit movie.', 'Experience the charm of Northern France in Bienvenue Chez les Ch''tis. Participate in hilarious mini-games inspired by the film''s iconic scenes, from bike riding to local cultural challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-bang-mini-europe-enfrdeesit', 'NDS', 'Big Bang Mini (Europe) (En,Fr,De,Es,It)', '2009', 'Shooter', 'Arkedo Studio', '1', 'Arcade Shooter', 'Shoot ''em up (Shmup) with fireworks-based combat.', 'Use fireworks to destroy enemies and clear the screen.', 'Innovative and artistic arcade shooter.', 'Big Bang Mini reinvents the shooter genre. Use the stylus to launch spectacular fireworks at enemies. Each level features a unique visual style and boss, making it one of the most creative titles on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-bang-mini-usa-enfrdeesit', 'NDS', 'Big Bang Mini (USA) (En,Fr,De,Es,It)', '2009', 'Shooter', 'Arkedo Studio', '1', 'Arcade Shooter', 'Shoot ''em up (Shmup) with fireworks-based combat.', 'Use fireworks to destroy enemies and clear the screen.', 'Innovative and artistic arcade shooter.', 'Big Bang Mini reinvents the shooter genre. Use the stylus to launch spectacular fireworks at enemies. Each level features a unique visual style and boss, making it one of the most creative titles on NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-brain-academy-europe-enfrdeesitnl', 'NDS', 'Big Brain Academy (Europe) (En,Fr,De,Es,It,Nl)', '2005', 'Educational', 'Nintendo', '1', 'Brain Training', 'Mental exercises and logic-based mini-games.', 'Increase your "Brain Weight" by solving rapid-fire puzzles.', 'Fast-paced competitive brain training.', 'Big Brain Academy challenges your mind in five categories: Compute, Identify, Analyze, Memorize, and Visualize. Perfect for solo play or competing with friends to see who has the heaviest brain.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-brain-academy-usa', 'NDS', 'Big Brain Academy (USA)', '2006', 'Educational', 'Nintendo', '1', 'Brain Training', 'Mental exercises and logic-based mini-games.', 'Increase your "Brain Weight" by solving rapid-fire puzzles.', 'Fast-paced competitive brain training.', 'Big Brain Academy challenges your mind in five categories: Compute, Identify, Analyze, Memorize, and Visualize. Perfect for solo play or competing with friends to see who has the heaviest brain.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-catch---bass-fishing-europe-enfrdeesit', 'NDS', 'Big Catch - Bass Fishing (Europe) (En,Fr,De,Es,It)', '2008', 'Sports', 'Prograph Research', '1', 'Fishing Simulation', 'Fishing simulation with realistic rod and reel mechanics.', 'Catch the biggest trophy bass in various tournament lakes.', 'Professional bass fishing simulation.', 'Big Catch: Bass Fishing brings the outdoors to your NDS. Use the touch screen to cast your line, lure fish, and fight to bring in massive bass in this realistic and relaxing sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-deal-the-europe', 'NDS', 'Big Deal, The (Europe)', '2007', 'Board Game', '10tacle Studios', '1', 'Digital Board Game', 'Card game and gambling simulation.', 'Master various casino games and win the high-stakes "Big Deal."', 'Comprehensive casino and card game pack.', 'Step into the world of high-stakes gambling with The Big Deal. Play Poker, Blackjack, and other casino favorites to build your bankroll and prove you''re the ultimate card shark on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-league-sports---summer-usa-enfr', 'NDS', 'Big League Sports - Summer (USA) (En,Fr)', '2009', 'Sports', 'Black Lantern Studios', '1', 'Sports Compilation', 'Sports mini-game collection with a summer theme.', 'Win gold medals in various summer athletic events.', 'Accessible summer sports competition.', 'Big League Sports: Summer features intuitive controls for tennis, beach volleyball, soccer, and more. Compete in quick-fire challenges designed for pick-up-and-play sports fun on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-mutha-truckers-europe-enfrdeesit', 'NDS', 'Big Mutha Truckers (Europe) (En,Fr,De,Es,It)', '2003', 'Racing', 'Eutechnyx', '1', 'Arcade Racing', 'Truck driving and business management simulation.', 'Deliver cargo across the highways and earn more than your rivals.', 'High-speed truck racing and trading.', 'Big Mutha Truckers is a mix of driving and commerce. Pick your trucker, haul goods across the county, and outrun the law in this humorous and fast-paced take on the trucking lifestyle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-mutha-truckers-usa', 'NDS', 'Big Mutha Truckers (USA)', '2003', 'Racing', 'Eutechnyx', '1', 'Arcade Racing', 'Truck driving and business management simulation.', 'Deliver cargo across the highways and earn more than your rivals.', 'High-speed truck racing and trading.', 'Big Mutha Truckers is a mix of driving and commerce. Pick your trucker, haul goods across the county, and outrun the law in this humorous and fast-paced take on the trucking lifestyle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-word-puzzle-book-europe-enfrdeesit', 'NDS', 'Big Word Puzzle Book (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'Maximum Family Games', '1', 'Word Puzzle', 'Word search, crosswords, and linguistic puzzles.', 'Solve a massive collection of word-based brain teasers.', 'The ultimate digital word puzzle book.', 'Big Word Puzzle Book offers hundreds of hours of vocabulary fun. Use the stylus to find hidden words, solve complex crosswords, and improve your spelling with an intuitive interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bigfoot---collision-course-europe-enfrdeesitnl', 'NDS', 'Bigfoot - Collision Course (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Racing', 'Team6 Game Studios', '1', 'Arcade Racing', 'Monster truck racing and destructible environments.', 'Race massive trucks and crush everything in your path.', 'Explosive monster truck racing action.', 'Take control of the legendary Bigfoot! Bigfoot: Collision Course features high-flying stunts, mud-splattered races, and plenty of car-crushing action across various off-road tracks on the NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('biggest-loser-usa-the-europe-ndsi-enhanced', 'NDS', 'Biggest Loser USA, The (Europe) (NDSi Enhanced)', '2010', 'Fitness', 'Blitz Games', '1', 'Fitness Training', 'Health, fitness, and nutrition tracking.', 'Follow a weight-loss program and reach your fitness goals.', 'Official fitness and diet management tool.', 'Based on the hit TV show, The Biggest Loser for NDS provides a personalized workout plan and calorie tracker. Use the NDSi camera features to track your progress and stay motivated.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('biggest-loser-the-usa-ndsi-enhanced', 'NDS', 'Biggest Loser, The (USA) (NDSi Enhanced)', '2010', 'Fitness', 'Blitz Games', '1', 'Fitness Training', 'Health, fitness, and nutrition tracking.', 'Follow a weight-loss program and reach your fitness goals.', 'Official fitness and diet management tool.', 'Based on the hit TV show, The Biggest Loser for NDS provides a personalized workout plan and calorie tracker. Use the NDSi camera features to track your progress and stay motivated.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bigs-2-the-usa', 'NDS', 'Bigs 2, The (USA)', '2009', 'Sports', 'Blue Castle Games', '1', 'Baseball Simulation', 'Arcade-style baseball with over-the-top power-ups.', 'Win the World Series with legendary "Big" plays.', 'Fast-paced arcade baseball action.', 'The Bigs 2 brings a heroic scale to baseball. Execute massive home runs and spectacular diving catches with simplified controls and high-energy graphics that make every inning exciting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('biker-mice-from-mars-europe', 'NDS', 'Biker Mice from Mars (Europe)', '2006', 'Action', 'Konami', '1', 'Action Racing', '3D vehicular combat and racing.', 'Defeat the evil Plutarkians and save the city of Chicago.', 'High-speed combat based on the cartoon.', 'Throttle, Modo, and Vinnie are back! Biker Mice from Mars features intense motorcycle combat. Use specialized weapons and upgrades to blast through enemies in this action-packed NDS racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('biker-mice-from-mars-usa', 'NDS', 'Biker Mice from Mars (USA)', '2006', 'Action', 'Konami', '1', 'Action Racing', '3D vehicular combat and racing.', 'Defeat the evil Plutarkians and save the city of Chicago.', 'High-speed combat based on the cartoon.', 'Throttle, Modo, and Vinnie are back! Biker Mice from Mars features intense motorcycle combat. Use specialized weapons and upgrades to blast through enemies in this action-packed NDS racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bikkuriman-daijiten-japan', 'NDS', 'Bikkuriman Daijiten (Japan)', '2007', 'Reference', 'Hudson Soft', '1', 'Encyclopedia', 'Digital encyclopedia and collection management.', 'Collect and learn about the entire Bikkuriman sticker series.', 'Interactive collector''s guide and trivia.', 'Bikkuriman Daijiten is the ultimate resource for fans of the iconic Japanese stickers. Browse thousands of entries, learn character lore, and manage your virtual collection in this comprehensive database.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('billiard-action-europe', 'NDS', 'Billiard Action (Europe)', '2008', 'Sports', 'Mud Duck Productions', '1', 'Billiards Simulation', 'Billiards and pool simulation with 3D physics.', 'Win pool tournaments and master various trick shots.', 'Authentic pocket billiards simulation.', 'Billiard Action offers precise touch-screen controls for pool enthusiasts. Play 9-ball, 8-ball, and rotation modes with realistic ball physics and a variety of challenging computer opponents on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('biohazard---deadly-silence-japan', 'NDS', 'Biohazard - Deadly Silence (Japan)', '2006', 'Action', 'Capcom', '1', 'Survival Horror', 'Survival horror with classic tank controls and new touch-screen features.', 'Survive the Spencer Mansion and uncover the Umbrella conspiracy.', 'The 10th anniversary remake of the original Resident Evil.', 'Biohazard: Deadly Silence brings the horror classic to NDS. It includes the original game plus a "Rebirth" mode featuring touch-screen puzzles and first-person knife battles, making it the definitive portable survival horror experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bionicle-heroes-europe-enfrdeesitda', 'NDS', 'Bionicle Heroes (Europe) (En,Fr,De,Es,It,Da)', '2006', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Third-person shooter with character swapping and LEGO building.', 'Defeat the Piraka and restore peace to the island of Voya Nui.', 'Action-packed LEGO Bionicle shooter.', 'Bionicle Heroes on NDS features fast-paced run-and-gun gameplay. Switch between different Toa masks to use unique elemental weapons and abilities while battling through beautifully rendered LEGO environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bionicle-heroes-japan', 'NDS', 'Bionicle Heroes (Japan)', '2006', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Third-person shooter with character swapping and LEGO building.', 'Defeat the Piraka and restore peace to the island of Voya Nui.', 'Action-packed LEGO Bionicle shooter.', 'Bionicle Heroes on NDS features fast-paced run-and-gun gameplay. Switch between different Toa masks to use unique elemental weapons and abilities while battling through beautifully rendered LEGO environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bionicle-heroes-usa', 'NDS', 'Bionicle Heroes (USA)', '2006', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Third-person shooter with character swapping and LEGO building.', 'Defeat the Piraka and restore peace to the island of Voya Nui.', 'Action-packed LEGO Bionicle shooter.', 'Bionicle Heroes on NDS features fast-paced run-and-gun gameplay. Switch between different Toa masks to use unique elemental weapons and abilities while battling through beautifully rendered LEGO environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bisanggu---exit-ds-korea', 'NDS', 'Bisanggu - Exit DS (Korea)', '2008', 'Puzzle', 'Sonnori', '1', 'Puzzle Adventure', 'Puzzle-solving focused on navigating a character to the exit.', 'Guide Mr. ESC through dangerous obstacles within a time limit.', 'A stylish and challenging escape puzzle game.', 'Bisanggu (Exit DS) is a portable version of the cult hit. Use strategy and quick thinking to lead survivors out of burning buildings and sinking ships in this high-contrast, aesthetically unique NDS puzzle title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('biz-nouryoku-ds-series---miryoku-kaikaku-japan', 'NDS', 'Biz Nouryoku DS Series - Miryoku Kaikaku (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Business Training', 'Business etiquette and social skill training simulation.', 'Improve your professional appeal and charisma in business settings.', 'A professional self-improvement guide for office life.', 'Miryoku Kaikaku is part of the Biz Nouryoku series. It provides interactive lessons on professional mannerisms, conversation techniques, and social grooming to help players excel in the Japanese corporate world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('biz-nouryoku-ds-series---wagokoro-no-moto-japan', 'NDS', 'Biz Nouryoku DS Series - Wagokoro no Moto (Japan)', '2006', 'Educational', 'Nintendo', '1', 'Business Training', 'Cultural education and etiquette training for traditional settings.', 'Master the "Japanese Heart" through etiquette and tradition.', 'A guide to Japanese culture and hospitality.', 'Wagokoro no Moto teaches the foundations of Japanese traditional manners. From tea ceremonies to proper bowing, this NDS title acts as a digital mentor for anyone looking to understand "Omotenashi" and cultural grace.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('biz-taiken-ds-series---kigyoudou---inshoku-japan', 'NDS', 'Biz Taiken DS Series - Kigyoudou - Inshoku (Japan)', '2007', 'Simulation', 'Nintendo', '1', 'Business Simulation', 'Business simulation and restaurant management.', 'Build and manage a successful food and beverage company.', 'A realistic restaurant entrepreneur simulator.', 'Kigyoudou - Inshoku puts you in the shoes of a food industry entrepreneur. Manage costs, design menus, and scale your business from a single shop to a major franchise in this deep Japanese business sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('black-cat---kuroneko-no-concerto-japan', 'NDS', 'Black Cat - Kuroneko no Concerto (Japan)', '2006', 'Adventure', 'Compile Heart', '1', 'Visual Novel', 'Narrative-driven adventure with mini-games based on the anime.', 'Solve a series of mysteries with Train Heartnet and friends.', 'Action-mystery adventure based on the hit manga.', 'Black Cat: Kuroneko no Concerto features the iconic Bounty Hunters. Engage in touch-screen investigations and battle enemies in a story-driven experience that captures the stylish vibe of the original series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('black-jack---hi-no-tori-hen-japan', 'NDS', 'Black Jack - Hi no Tori Hen (Japan)', '2004', 'Board Game', 'Alfa System', '1', 'Card Game', 'Surgical simulation and medical adventure.', 'Perform life-saving surgeries and solve medical mysteries.', 'Medical drama based on Osamu Tezuka''s manga.', 'Black Jack: Hi no Tori Hen combines the world of Black Jack and Phoenix. Use the NDS stylus as a scalpel to perform precision surgeries while following a deep narrative involving the world''s greatest unlicensed surgeon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('black-sigil---blade-of-the-exiled-usa', 'NDS', 'Black Sigil - Blade of the Exiled (USA)', '2009', 'RPG', 'Studio Archcraft', '1', 'Classic JRPG', 'Turn-based tactical RPG with classic 16-bit styling.', 'Uncover the mystery of the Cursed and save the world of Belatyr.', 'A nostalgic, deep turn-based fantasy RPG.', 'Black Sigil: Blade of the Exiled is a love letter to SNES-era RPGs. Explore a world where magic is common and your protagonist is the only one without it, featuring a massive world map and complex tactical combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blades-of-thunder-ii-usa', 'NDS', 'Blades of Thunder II (USA)', '2005', 'Action', 'Monolith Productions', '1', 'Arcade Shooter', 'Aerial combat and flight simulation with modern jets.', 'Complete high-stakes flight missions and dogfight enemy pilots.', 'Intense arcade flight combat action.', 'Blades of Thunder II takes to the skies on NDS. Pilot advanced fighter jets through 20 different missions, featuring 3D dogfights and diverse objectives from air-to-ground strikes to high-speed interceptions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blazer-drive-japan', 'NDS', 'Blazer Drive (Japan)', '2008', 'RPG', 'Imageepoch', '1', 'Action RPG', 'Card-based battle RPG with a futuristic setting.', 'Master the "Blazer" powers and win the ultimate tournament.', 'Futuristic card-battling adventure.', 'Blazer Drive is based on the manga by Seishi Kishimoto. Use stickers (MyStickers) to power up your weapons and engage in strategic, fast-paced card battles in a vibrant, neon-lit future on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bleach---dark-souls-europe-enfrdeesit', 'NDS', 'Bleach - Dark Souls (Europe) (En,Fr,De,Es,It)', '2007', 'Action', 'Treasure', '1', 'Fighting', '2D fighting game with massive rosters and 4-player battles.', 'Fight through the Soul Society and master your Bankai.', 'The ultimate portable anime fighting game.', 'Bleach: Dark Souls features over 40 playable characters. With refined combat mechanics and intense 4-player local wireless battles, it is widely considered one of the best fighting titles on the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bleach---dark-souls-usa', 'NDS', 'Bleach - Dark Souls (USA)', '2007', 'Action', 'Treasure', '1', 'Fighting', '2D fighting game with massive rosters and 4-player battles.', 'Fight through the Soul Society and master your Bankai.', 'The ultimate portable anime fighting game.', 'Bleach: Dark Souls features over 40 playable characters. With refined combat mechanics and intense 4-player local wireless battles, it is widely considered one of the best fighting titles on the Nintendo DS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bleach---the-3rd-phantom-europe-enfr', 'NDS', 'Bleach - The 3rd Phantom (Europe) (En,Fr)', '2009', 'Strategy', 'Treasure', '1', 'Tactical RPG', 'Tactical turn-based RPG with an original storyline.', 'Lead a squad of Soul Reapers and uncover a hidden past.', 'Strategy RPG set in the Bleach universe.', 'Bleach: The 3rd Phantom introduces two original protagonists. Manage your team''s stats, explore the Seireitei, and engage in grid-based tactical battles featuring stunning 2D animations of iconic Bleach moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bleach---the-3rd-phantom-japan', 'NDS', 'Bleach - The 3rd Phantom (Japan)', '2009', 'Strategy', 'Treasure', '1', 'Tactical RPG', 'Tactical turn-based RPG with an original storyline.', 'Lead a squad of Soul Reapers and uncover a hidden past.', 'Strategy RPG set in the Bleach universe.', 'Bleach: The 3rd Phantom introduces two original protagonists. Manage your team''s stats, explore the Seireitei, and engage in grid-based tactical battles featuring stunning 2D animations of iconic Bleach moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bleach---the-3rd-phantom-usa', 'NDS', 'Bleach - The 3rd Phantom (USA)', '2009', 'Strategy', 'Treasure', '1', 'Tactical RPG', 'Tactical turn-based RPG with an original storyline.', 'Lead a squad of Soul Reapers and uncover a hidden past.', 'Strategy RPG set in the Bleach universe.', 'Bleach: The 3rd Phantom introduces two original protagonists. Manage your team''s stats, explore the Seireitei, and engage in grid-based tactical battles featuring stunning 2D animations of iconic Bleach moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bleach---the-blade-of-fate-europe-enfrdeesit', 'NDS', 'Bleach - The Blade of Fate (Europe) (En,Fr,De,Es,It)', '2007', 'Action', 'Treasure', '1', 'Fighting', '2D fighting game featuring a card-based "Spirit Card" system.', 'Battle through the "Rescue Rukia" arc and master combat skills.', 'Fast-paced anime fighter with strategic cards.', 'Bleach: The Blade of Fate offers fluid, high-speed combat. Use the touch screen to activate Spirit Cards that boost stats or hinder enemies, making every 1-on-1 duel a mix of reflexes and strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bleach---the-blade-of-fate-usa', 'NDS', 'Bleach - The Blade of Fate (USA)', '2007', 'Action', 'Treasure', '1', 'Fighting', '2D fighting game featuring a card-based "Spirit Card" system.', 'Battle through the "Rescue Rukia" arc and master combat skills.', 'Fast-paced anime fighter with strategic cards.', 'Bleach: The Blade of Fate offers fluid, high-speed combat. Use the touch screen to activate Spirit Cards that boost stats or hinder enemies, making every 1-on-1 duel a mix of reflexes and strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bleach-ds---souten-ni-kakeru-unmei-japan', 'NDS', 'Bleach DS - Souten ni Kakeru Unmei (Japan)', '2006', 'Action', 'Treasure', '1', 'Fighting', '2D fighting game featuring a card-based "Spirit Card" system.', 'Battle through the "Rescue Rukia" arc and master combat skills.', 'Fast-paced anime fighter with strategic cards.', 'Bleach: The Blade of Fate offers fluid, high-speed combat. Use the touch screen to activate Spirit Cards that boost stats or hinder enemies, making every 1-on-1 duel a mix of reflexes and strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bleach-ds-2nd---kokui-hirameku-requiem-japan', 'NDS', 'Bleach DS 2nd - Kokui Hirameku Requiem (Japan)', '2007', 'Action', 'Treasure', '1', 'Fighting', '2D fighting game with massive rosters and 4-player battles.', 'Fight through the Soul Society and master your Bankai.', 'The ultimate portable anime fighting game.', 'Bleach DS 2nd - Kokui Hirameku Requiem is the Japanese version of Dark Souls. It features an expanded roster and improved deck mechanics for the Spirit Card system, delivering top-tier 2D fighting action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bleach-ds-4th---flame-bringer-japan', 'NDS', 'Bleach DS 4th - Flame Bringer (Japan)', '2009', 'Action', 'Treasure', '1', 'Fighting', 'Side-scrolling action brawler with elemental powers.', 'Use the power of flames to defeat enemies and bosses.', 'Action-focused Bleach brawler.', 'Bleach DS 4th - Flame Bringer departs from the fighting genre for pure side-scrolling action. Control Ichigo and use the stylus to unleash powerful spiritual attacks in this fast-paced, level-based adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blood-bowl-europe-enfrdeesit', 'NDS', 'Blood Bowl (Europe) (En,Fr,De,Es,It)', '2009', 'Strategy', 'Cyanide Studio', '1', 'Turn-Based Strategy', 'Turn-based fantasy football with brutal violence.', 'Lead your team of Orcs, Elves, or Humans to victory in the Bowl.', 'Violent strategy-sports hybrid.', 'Blood Bowl on NDS is a faithful adaptation of the Warhammer-themed board game. Combine deep tactical positioning with random acts of carnage as you coach your team through a bloody and hilarious season.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blood-of-bahamut-japan', 'NDS', 'Blood of Bahamut (Japan)', '2009', 'RPG', 'Square Enix', '1', 'Action RPG', 'Real-time tactical action RPG against colossal enemies.', 'Defeat the giant "Beasts" and protect the world of Bahamut.', 'Epic monster-hunting tactical RPG.', 'Blood of Bahamut features massive bosses that span both NDS screens. Coordinate with your team to dismantle these giants piece by piece in a visually spectacular action-RPG from Square Enix.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blue-dragon---awakened-shadow-europe', 'NDS', 'Blue Dragon - Awakened Shadow (Europe)', '2008', 'RPG', 'Mistwalker', '1', 'JRPG', 'Action-RPG with deep character customization and real-time combat.', 'Save the world from a new shadow threat and collect fragments.', 'Third entry in the Blue Dragon series.', 'Blue Dragon: Awakened Shadow allows you to create your own protagonist. Explore a vast world, customize your shadow''s abilities, and engage in real-time battles in this expansive RPG journey for NDS.');
