INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blue-dragon-plus-europe-enfrdeesit', 'NDS', 'Blue Dragon Plus (Europe) (En,Fr,De,Es,It)', '2009', 'RPG', 'Mistwalker', '1', 'Strategy RPG', 'Real-time tactical RPG with unit management.', 'Command Shu and his friends to defeat a new mechanical threat.', 'A strategic sequel to the Blue Dragon saga.', 'Blue Dragon Plus shifts the series to a tactical real-time strategy format. Control multiple units on the battlefield, manage powerful shadows, and explore a deep story that takes place one year after the original game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blue-dragon-plus-japan', 'NDS', 'Blue Dragon Plus (Japan)', '2009', 'RPG', 'Mistwalker', '1', 'Strategy RPG', 'Real-time tactical RPG with unit management.', 'Command Shu and his friends to defeat a new mechanical threat.', 'A strategic sequel to the Blue Dragon saga.', 'Blue Dragon Plus shifts the series to a tactical real-time strategy format. Control multiple units on the battlefield, manage powerful shadows, and explore a deep story that takes place one year after the original game.');
