INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blumen-&-muster-puzzle---echter-puzzlespass-fuer-unterwegs-europe-enfrdeesit', 'NDS', 'Blumen & Muster Puzzle - Echter Puzzlespass fuer Unterwegs (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'dtp entertainment', '1', 'Classic Puzzle', 'Digital jigsaw puzzle simulation with floral themes.', 'Solve beautiful puzzles featuring flowers and patterns.', 'A relaxing digital floral jigsaw collection.', 'Blumen & Muster Puzzle offers a peaceful puzzling experience on NDS. With varying difficulty levels and high-quality images of nature and intricate patterns, it''s perfect for casual play on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bob-the-builder---festival-of-fun-europe-enfrdenl', 'NDS', 'Bob the Builder - Festival of Fun (Europe) (En,Fr,De,Nl)', '2009', 'Adventure', 'Redtribe', '1', 'Kids Adventure', 'Mini-game collection and simple construction tasks.', 'Help Bob and his team prepare for the big festival.', 'Preschool construction adventure.', 'Bob the Builder: Festival of Fun is designed for young players. Use the touch screen to fix buildings, complete puzzles, and help the "Can-Do" crew make the festival a success.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boing!-docomodake-ds-europe-enfrdeesit', 'NDS', 'Boing! Docomodake DS (Europe) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'AQ Interactive', '1', 'Casual Puzzle', 'Physics-based puzzle platforming with splitting mechanics.', 'Use the Docomodake''s ability to split and merge to reach the exit.', 'Creative and quirky mushroom-based puzzle game.', 'Boing! Docomodake DS is a unique puzzler based on the famous Japanese mascot. Control Papa Docomodake and split him into smaller mushrooms to solve environmental riddles and navigate tricky platforms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boing!-docomodake-ds-usa-enfrdeesit', 'NDS', 'Boing! Docomodake DS (USA) (En,Fr,De,Es,It)', '2009', 'Puzzle', 'AQ Interactive', '1', 'Casual Puzzle', 'Physics-based puzzle platforming with splitting mechanics.', 'Use the Docomodake''s ability to split and merge to reach the exit.', 'Creative and quirky mushroom-based puzzle game.', 'Boing! Docomodake DS is a unique puzzler based on the famous Japanese mascot. Control Papa Docomodake and split him into smaller mushrooms to solve environmental riddles and navigate tricky platforms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boku-to-sim-no-machi---agent---nazo-no-kaitou-kara-hihou-o-mamore-daisakusen!-japan-enja', 'NDS', 'Boku to Sim no Machi - Agent - Nazo no Kaitou kara Hihou o Mamore Daisakusen! (Japan) (En,Ja)', '2007', 'Simulation', 'EA Japan', '1', 'Life Simulation', 'Social simulation and mystery-solving adventure.', 'Solve cases and protect treasures from a mysterious thief.', 'MySims Agents - Detective adventure.', 'Play as a secret agent in the MySims universe. Solve puzzles, collect clues, and use high-tech gadgets to track down the thief and protect the city in this charming adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boku-to-sim-no-machi---kingdom-japan', 'NDS', 'Boku to Sim no Machi - Kingdom (Japan)', '2007', 'Simulation', 'EA Japan', '1', 'Life Simulation', 'City-building and social simulation in a royal setting.', 'Rebuild a kingdom and attract new residents.', 'MySims Kingdom - Creative building sim.', 'Help King Roland restore his realm. Use the stylus to build furniture and houses, complete quests for eccentric townspeople, and bring the MySims Kingdom back to its former glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boku-to-sim-no-machi---party-japan', 'NDS', 'Boku to Sim no Machi - Party (Japan)', '2008', 'Simulation', 'EA Japan', '1', 'Party Simulation', 'Competitive mini-games and social party simulation.', 'Compete in various challenges to win the party crown.', 'MySims Party - Fun mini-game collection.', 'Host a huge event in the MySims world. Compete in dozens of fast-paced mini-games against your favorite Sims to earn points and prove you are the ultimate party host.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boku-to-sim-no-machi---racing-japan', 'NDS', 'Boku to Sim no Machi - Racing (Japan)', '2008', 'Racing', 'EA Japan', '1', 'Arcade Racing', 'Kart racing and vehicle customization.', 'Win races and become the champion of the MySims circuit.', 'MySims Racing - High-speed kart action.', 'Customize your vehicle from the ground up and race against rival Sims. Use unique power-ups and master drifting to win grand prix events across diverse tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boku-to-sim-no-machi---resort-ni-genki-o-torimodosou!-japan', 'NDS', 'Boku to Sim no Machi - Resort ni Genki o Torimodosou! (Japan)', '2008', 'Simulation', 'EA Japan', '1', 'Life Simulation', 'Resort management and social simulation.', 'Revitalize a rundown island and attract tourists.', 'MySims - Tropical island management.', 'Take charge of a tropical resort in the MySims world. Build attractions, manage guest needs, and turn a quiet island into a bustling holiday destination using your creativity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boku-wa-koukuu-kanseikan-ds---air-traffic-controller-japan', 'NDS', 'Boku wa Koukuu Kanseikan DS - Air Traffic Controller (Japan)', '2009', 'Simulation', 'Sonic Powered', '1', 'Air Traffic Control', 'Simulation and time management as an air traffic controller.', 'Manage runway traffic and ensure safe landings and takeoffs.', 'Realistic air traffic control simulator.', 'Boku wa Koukuu Kanseikan (Air Traffic Controller) challenges your focus. Coordinate multiple planes, manage weather conditions, and prevent delays in this stressful but rewarding professional sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokujou-monogatari---colobockle-station-japan', 'NDS', 'Bokujou Monogatari - Colobockle Station (Japan)', '2005', 'Simulation', 'Marvelous Interactive', '1', 'Farming Simulation', 'Farming simulation and life management.', 'Build a successful farm and rescue the Harvest Goddess.', 'Harvest Moon DS - Classic farming RPG.', 'Experience the classic farming life in Forget-Me-Not Valley. Grow crops, raise animals, and find love while working to restore the power of the Harvest Goddess through your hard work.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokujou-monogatari---colobockle-station-japan-rev-2', 'NDS', 'Bokujou Monogatari - Colobockle Station (Japan) (Rev 2)', '2005', 'Simulation', 'Marvelous Interactive', '1', 'Farming Simulation', 'Farming simulation and life management.', 'Build a successful farm and rescue the Harvest Goddess.', 'Harvest Moon DS - Classic farming RPG.', 'Experience the classic farming life in Forget-Me-Not Valley. Grow crops, raise animals, and find love while working to restore the power of the Harvest Goddess through your hard work.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokujou-monogatari---colobockle-station-for-girl-japan', 'NDS', 'Bokujou Monogatari - Colobockle Station for Girl (Japan)', '2006', 'Simulation', 'Marvelous Interactive', '1', 'Farming Simulation', 'Farming simulation and life management for female protagonists.', 'Manage your farm and choose between several bachelors.', 'Harvest Moon DS Cute - Farming romance sim.', 'The female-focused version of the classic DS farm sim. Choose your character, build a thriving farm, and build relationships with the local townspeople to find your perfect match.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokujou-monogatari---futago-no-mura-japan', 'NDS', 'Bokujou Monogatari - Futago no Mura (Japan)', '2010', 'Simulation', 'Marvelous Interactive', '1', 'Farming Simulation', 'Farming simulation with a dual-village mechanic.', 'Choose between two rival villages and foster friendship.', 'Harvest Moon: The Tale of Two Towns.', 'Pick your home between the European-style Bluebell or the Asian-style Konohana. Manage your farm, compete in cooking festivals, and try to reunite the two feuding villages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokujou-monogatari---kimi-to-sodatsu-shima-japan', 'NDS', 'Bokujou Monogatari - Kimi to Sodatsu Shima (Japan)', '2008', 'Simulation', 'Marvelous Interactive', '1', 'Farming Simulation', 'Farming simulation and island exploration.', 'Develop a deserted island and grow your farm.', 'Harvest Moon: Island of Happiness.', 'After being shipwrecked, you must build a new life. Use the touch screen to plant crops and interact with other survivors to turn a lonely island into a thriving community.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokujou-monogatari---kirakira-taiyou-to-nakama-tachi-japan', 'NDS', 'Bokujou Monogatari - KiraKira Taiyou to Nakama-tachi (Japan)', '2009', 'Simulation', 'Marvelous Interactive', '1', 'Farming Simulation', 'Farming simulation with updated mechanics and characters.', 'Collect Sun Stones to raise sunken islands.', 'Harvest Moon: Sunshine Islands.', 'A spiritual successor to Island of Happiness. Expand your world by raising islands from the sea, allowing for more farming, more animals, and new characters to meet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokujou-monogatari---youkoso!-kaze-no-bazaar-e-japan', 'NDS', 'Bokujou Monogatari - Youkoso! Kaze no Bazaar e (Japan)', '2008', 'Simulation', 'Marvelous Interactive', '1', 'Farming Simulation', 'Farming simulation with a focus on marketplace sales.', 'Produce goods and sell them at the weekly bazaar.', 'Harvest Moon: Grand Bazaar.', 'Focus on the economy of farming. Grow the best crops and create processed goods to become the top vendor at the town''s famous bustling marketplace events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokura-no-taiyou---django-&-sabata-japan', 'NDS', 'Bokura no Taiyou - Django & Sabata (Japan)', '2006', 'Action', 'Raum', '1', 'Action RPG', 'Isometric action-adventure with stealth and sunlight mechanics.', 'Battle vampires and undead in a gothic fantasy world.', 'Lunar Knights - Vampiric action RPG.', 'Known as Lunar Knights, this game uses a digital "sunlight" system to power your weapons. Control two heroes with different playstyles in a high-quality action RPG from Kojima Productions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokura-no-television-game-kentei---pikotto!-udedameshi-japan', 'NDS', 'Bokura no Television Game Kentei - Pikotto! Udedameshi (Japan)', '2008', 'Party', 'Nintendo', '1', 'Quiz Game', 'Quiz and mini-game collection based on retro TV games.', 'Test your skills across various classic-style challenges.', 'Retro TV game challenge and trivia.', 'Compete in a variety of mini-games that pay homage to the golden age of television gaming. Test your reflexes and knowledge in this quirky Japanese collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokura-wa-kaseki-horider-japan', 'NDS', 'Bokura wa Kaseki Horider (Japan)', '2008', 'RPG', 'Red Entertainment', '1', 'Monster Collecting RPG', 'Fossil hunting and dinosaur battling RPG.', 'Excavate fossils, revive dinosaurs, and win battles.', 'Fossil Fighters - Dinosaur RPG.', 'Dig up fossils using the stylus, clean them carefully, and bring prehistoric creatures back to life to compete in tactical arena battles against other "Fossil Fighters."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bolt-europe-enfrdeesitnl', 'NDS', 'Bolt (Europe) (En,Fr,De,Es,It,Nl)', '2008', 'Action', 'Altron', '1', 'Action Adventure', '3D action-adventure based on the Disney film.', 'Use your super-powers to save Penny from the evil Dr. Calico.', 'Heroic action with Disney''s super-dog.', 'Play as Bolt and Penny in this high-energy adventure. Use Bolt''s sonic bark and laser eyes or Penny''s stealth gadgets to fight through various global locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bolt-europe-ensvnoda', 'NDS', 'Bolt (Europe) (En,Sv,No,Da)', '2008', 'Action', 'Altron', '1', 'Action Adventure', '3D action-adventure based on the Disney film.', 'Use your super-powers to save Penny from the evil Dr. Calico.', 'Heroic action with Disney''s super-dog.', 'Play as Bolt and Penny in this high-energy adventure. Use Bolt''s sonic bark and laser eyes or Penny''s stealth gadgets to fight through various global locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bolt-japan-rev-1', 'NDS', 'Bolt (Japan) (Rev 1)', '2008', 'Action', 'Altron', '1', 'Action Adventure', '3D action-adventure based on the Disney film.', 'Use your super-powers to save Penny from the evil Dr. Calico.', 'Heroic action with Disney''s super-dog.', 'Play as Bolt and Penny in this high-energy adventure. Use Bolt''s sonic bark and laser eyes or Penny''s stealth gadgets to fight through various global locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bolt-usa-enfres', 'NDS', 'Bolt (USA) (En,Fr,Es)', '2008', 'Action', 'Altron', '1', 'Action Adventure', '3D action-adventure based on the Disney film.', 'Use your super-powers to save Penny from the evil Dr. Calico.', 'Heroic action with Disney''s super-dog.', 'Play as Bolt and Penny in this high-energy adventure. Use Bolt''s sonic bark and laser eyes or Penny''s stealth gadgets to fight through various global locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomber-man-japan', 'NDS', 'Bomber Man (Japan)', '2008', 'Action', 'Hudson Soft', '1', 'Action Puzzle', 'Classic maze-based bomb-laying action.', 'Defeat all enemies and find the exit in each stage.', 'The definitive handheld Bomberman.', 'Experience the classic Bomberman gameplay with 100 stages in solo mode and intense 8-player local wireless battles. It''s the ultimate version of the timeless "blow-up-your-friends" strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomber-man-japan-rev-1', 'NDS', 'Bomber Man (Japan) (Rev 1)', '2008', 'Action', 'Hudson Soft', '1', 'Action Puzzle', 'Classic maze-based bomb-laying action.', 'Defeat all enemies and find the exit in each stage.', 'The definitive handheld Bomberman.', 'Experience the classic Bomberman gameplay with 100 stages in solo mode and intense 8-player local wireless battles. It''s the ultimate version of the timeless "blow-up-your-friends" strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomber-man-story-ds-japan', 'NDS', 'Bomber Man Story DS (Japan)', '2007', 'RPG', 'Hudson Soft', '1', 'Action RPG', 'Adventure RPG with classic Bomberman mechanics.', 'Explore a planet and use bombs to solve environmental puzzles.', 'Bomberman Land Touch! - Adventure edition.', 'This title blends traditional Bomberman battles with a deep quest mode. Explore a vibrant world, complete mini-games, and use your bombs to unlock new paths in this expanded adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-europe-enfrdeesit', 'NDS', 'Bomberman (Europe) (En,Fr,De,Es,It)', '2006', 'Action', 'Hudson Soft', '1-4', 'Action Maze', 'Classic maze-based bomb-laying action.', 'Defeat all enemies and find the exit in each stage.', 'The definitive handheld Bomberman.', 'Experience the classic Bomberman gameplay with 100 stages in solo mode and intense 8-player local wireless battles. It''s the ultimate version of the timeless "blow-up-your-friends" strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-usa', 'NDS', 'Bomberman (USA)', '2006', 'Action', 'Hudson Soft', '1-4', 'Action Maze', 'Classic maze-based bomb-laying action.', 'Defeat all enemies and find the exit in each stage.', 'The definitive handheld Bomberman.', 'Experience the classic Bomberman gameplay with 100 stages in solo mode and intense 8-player local wireless battles. It''s the ultimate version of the timeless "blow-up-your-friends" strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-2-europe-enfrdeesit', 'NDS', 'Bomberman 2 (Europe) (En,Fr,De,Es,It)', '2007', 'Action', 'Hudson Soft', '1-4', 'Action Maze', 'Classic bomb-laying action with a futuristic skin.', 'Defeat enemies and customize your Bomberman with armor parts.', 'Enhanced sci-fi Bomberman action.', 'Bomberman 2 (known as Custom Battler Bomberman in Japan) brings deep customization to the classic formula. Collect over 160 parts to upgrade your character''s abilities and tackle a mission-based single-player campaign or 8-player wireless battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-land-touch!-europe-enfrdeesit', 'NDS', 'Bomberman Land Touch! (Europe) (En,Fr,De,Es,It)', '2006', 'Adventure', 'Hudson Soft', '1', 'Adventure Puzzle', 'Mini-game collection and theme park exploration.', 'Solve puzzles and win attraction games to earn pieces.', 'A fun-filled Bomberman theme park.', 'Bomberman Land Touch! offers a unique mix of exploration and variety. Use the touch screen to master over 30 mini-games in the theme park, while also enjoying the legendary "Classic Mode" for traditional bomb-blasting multiplayer fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-land-touch!-usa', 'NDS', 'Bomberman Land Touch! (USA)', '2006', 'Adventure', 'Hudson Soft', '1', 'Adventure Puzzle', 'Mini-game collection and theme park exploration.', 'Solve puzzles and win attraction games to earn pieces.', 'A fun-filled Bomberman theme park.', 'Bomberman Land Touch! offers a unique mix of exploration and variety. Use the touch screen to master over 30 mini-games in the theme park, while also enjoying the legendary "Classic Mode" for traditional bomb-blasting multiplayer fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-land-touch!-2-europe-enfrdeesit', 'NDS', 'Bomberman Land Touch! 2 (Europe) (En,Fr,De,Es,It)', '2008', 'Adventure', 'Hudson Soft', '1', 'Adventure Puzzle', 'Sequel featuring a tropical island theme park and mini-games.', 'Navigate the Star Bomber island and win the tournament.', 'Expanded mini-game adventure.', 'Bomberman Land Touch! 2 brings the party to a tropical setting. With a longer story mode, improved touch-screen controls for mini-games, and a full-featured Battle Mode, it''s a comprehensive package for fans of the explosive mascot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-land-touch!-2-usa', 'NDS', 'Bomberman Land Touch! 2 (USA)', '2008', 'Adventure', 'Hudson Soft', '1', 'Adventure Puzzle', 'Sequel featuring a tropical island theme park and mini-games.', 'Navigate the Star Bomber island and win the tournament.', 'Expanded mini-game adventure.', 'Bomberman Land Touch! 2 brings the party to a tropical setting. With a longer story mode, improved touch-screen controls for mini-games, and a full-featured Battle Mode, it''s a comprehensive package for fans of the explosive mascot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-story-ds-europe-enfrdeesit', 'NDS', 'Bomberman Story DS (Europe) (En,Fr,De,Es,It)', '2007', 'RPG', 'Hudson Soft', '1', 'Action RPG', 'Action-RPG with puzzle-solving and real-time battles.', 'Journey across the planet to prevent a galactic disaster.', 'A story-driven Bomberman adventure.', 'Bomberman Story DS blends classic bomb mechanics with RPG elements. Interact with NPCs, explore diverse biomes, and use special "Color Bombs" to solve environmental puzzles and defeat giant bosses in a grand quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boogie-europe-enfrdeesitnlpt', 'NDS', 'Boogie (Europe) (En,Fr,De,Es,It,Nl,Pt)', '2007', 'Music', 'EA Montreal', '1', 'Rhythm Dance', 'Rhythm and dance simulation with character customization.', 'Outdance and outsing your rivals to become a star.', 'A vibrant musical party game.', 'Boogie for NDS invites you to tap and slide to the rhythm. Customize your own "Boog" character and compete in various dancing and singing challenges set to a licensed soundtrack of popular hits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boogie-usa-enfres', 'NDS', 'Boogie (USA) (En,Fr,Es)', '2007', 'Music', 'EA Montreal', '1', 'Rhythm Dance', 'Rhythm and dance simulation with character customization.', 'Outdance and outsing your rivals to become a star.', 'A vibrant musical party game.', 'Boogie for NDS invites you to tap and slide to the rhythm. Customize your own "Boog" character and compete in various dancing and singing challenges set to a licensed soundtrack of popular hits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bookworm-usa', 'NDS', 'Bookworm (USA)', '2009', 'Puzzle', 'PopCap Games', '1', 'Word Puzzle', 'Word-building puzzle gameplay with a charming bookworm theme.', 'Link letters to form words and feed the hungry Lex.', 'Addictive word-puzzle classic.', 'Bookworm for NDS is a must-play for word lovers. Connect adjacent letters to form long words, clear burning tiles before they reach the bottom, and use bonus tiles to boost your score in this polished portable version of the PopCap hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bouken-ou-beet---vandel-vs-busters-japan', 'NDS', 'Bouken-ou Beet - Vandel vs. Busters (Japan)', '2005', 'RPG', 'Dimps', '1', 'Action RPG', 'Tactical action-RPG based on the popular manga/anime.', 'Battle Vandels and protect the world as a certified Buster.', 'High-action anime RPG.', 'Bouken-ou Beet: Vandel vs. Busters lets you lead Beet’s squad into battle. Master the "Saiga" weapon system and engage in strategic combat against the dark forces of the Vandels in this faithful adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boulder-dash---rocks!-europe-enfrdeesit', 'NDS', 'Boulder Dash - Rocks! (Europe) (En,Fr,De,Es,It)', '2007', 'Puzzle', '10TACLE Studios', '1', 'Classic Puzzle', 'Physics-based puzzle-action in subterranean mines.', 'Collect diamonds while avoiding falling rocks and enemies.', 'Modern revival of the arcade classic.', 'Boulder Dash - Rocks! brings Rockford to the NDS with 3D graphics. Navigate treacherous caves, solve gravity-based puzzles, and enjoy new game modes and power-ups that revitalize the legendary 80s gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boule-&-bill---vive-les-vacances!-france', 'NDS', 'Boule & Bill - Vive les Vacances! (France)', '2008', 'Adventure', 'Mindscape', '1', 'Kids Adventure', 'Mini-game collection based on the French comic series.', 'Join Boule and his dog Bill for a series of summer activities.', 'Lighthearted family mini-games.', 'Boule & Bill: Vive les Vacances! offers a variety of touch-screen challenges inspired by the classic comics. Enjoy various sports, puzzles, and chores turned into fun games perfect for younger players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brain-age---train-your-brain-in-minutes-a-day!-usa', 'NDS', 'Brain Age - Train Your Brain in Minutes a Day! (USA)', '2006', 'Educational', 'Nintendo', '1', 'Brain Training', 'Mental exercises and cognitive training.', 'Stimulate your brain with daily math and logic drills.', 'The pioneer of brain training on DS.', 'Brain Age (Dr. Kawashima''s Brain Training) helps you calculate your "Brain Age." Perform daily exercises like "Stroop Tests" and rapid-fire math to improve your focus and cognitive speed in just minutes a day.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brain-age---train-your-brain-in-minutes-a-day!-usa-rev-1', 'NDS', 'Brain Age - Train Your Brain in Minutes a Day! (USA) (Rev 1)', '2006', 'Educational', 'Nintendo', '1', 'Brain Training', 'Mental exercises and cognitive training.', 'Stimulate your brain with daily math and logic drills.', 'The pioneer of brain training on DS.', 'Brain Age (Dr. Kawashima''s Brain Training) helps you calculate your "Brain Age." Perform daily exercises like "Stroop Tests" and rapid-fire math to improve your focus and cognitive speed in just minutes a day.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brain-age-2---more-training-in-minutes-a-day!-usa-enfres', 'NDS', 'Brain Age 2 - More Training in Minutes a Day! (USA) (En,Fr,Es)', '2007', 'Educational', 'Nintendo', '1', 'Brain Training', 'Advanced mental exercises and logic puzzles.', 'Challenge your brain with even more complex daily drills.', 'Deep and challenging brain trainer.', 'Brain Age 2 expands on the original with all-new exercises. Master Sudoku, play "Mastermind" style games, and participate in musical and word-based challenges to keep your mind sharper than ever.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brain-assist-europe-enfrdeesit', 'NDS', 'Brain Assist (Europe) (En,Fr,De,Es,It)', '2008', 'Educational', 'Interchannel', '1', 'Brain Training', 'Quick-fire mental agility and memory tests.', 'Boost your right-brain performance through rapid mini-games.', 'Fast-paced cognitive assistant.', 'Brain Assist focuses on speed and observation. Through a series of rapid-fire tests designed by health experts, you can improve your memory, concentration, and analytical skills in a colorful, accessible format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brain-assist-usa-enfrdeesit', 'NDS', 'Brain Assist (USA) (En,Fr,De,Es,It)', '2008', 'Educational', 'Interchannel', '1', 'Brain Training', 'Quick-fire mental agility and memory tests.', 'Boost your right-brain performance through rapid mini-games.', 'Fast-paced cognitive assistant.', 'Brain Assist focuses on speed and observation. Through a series of rapid-fire tests designed by health experts, you can improve your memory, concentration, and analytical skills in a colorful, accessible format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brain-boost---beta-wave-usa', 'NDS', 'Brain Boost - Beta Wave (USA)', '2008', 'Educational', 'Majesco', '1', 'Brain Training', 'Memory and concentration drills using the "Beta Wave" method.', 'Improve your focus and memory with repetitive exercises.', 'Scientific memory-building tool.', 'Brain Boost - Beta Wave is designed to enhance your cognitive retention. Practice identifying patterns and remembering sequences in a structured way to help keep your brain alert and active.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brain-boost---gamma-wave-usa', 'NDS', 'Brain Boost - Gamma Wave (USA)', '2008', 'Educational', 'Majesco', '1', 'Brain Training', 'Math and logic drills using the "Gamma Wave" method.', 'Sharpen your logical thinking and calculation skills.', 'Scientific logic-building tool.', 'Brain Boost - Gamma Wave targets the logical side of your brain. Solve puzzles and math problems under pressure to improve your mental flexibility and problem-solving speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brain-buster---puzzle-pak-europe-enfresit', 'NDS', 'Brain Buster - Puzzle Pak (Europe) (En,Fr,Es,It)', '2007', 'Puzzle', 'Midway', '1', 'Puzzle Collection', 'A massive collection of classic logic puzzles.', 'Solve hundreds of Sudoku, Kakuro, and Slitherlink puzzles.', 'The ultimate logic puzzle package.', 'Brain Buster - Puzzle Pak is a dream for puzzle enthusiasts. Featuring five different types of logic games and hundreds of levels, it offers a clean, touch-responsive interface for hours of mental stimulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brain-buster---puzzle-pak-usa', 'NDS', 'Brain Buster - Puzzle Pak (USA)', '2007', 'Puzzle', 'Midway', '1', 'Puzzle Collection', 'A massive collection of classic logic puzzles.', 'Solve hundreds of Sudoku, Kakuro, and Slitherlink puzzles.', 'The ultimate logic puzzle package.', 'Brain Buster - Puzzle Pak is a dream for puzzle enthusiasts. Featuring five different types of logic games and hundreds of levels, it offers a clean, touch-responsive interface for hours of mental stimulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brain-challenge-europe-enfrdeesitnl', 'NDS', 'Brain Challenge (Europe) (En,Fr,De,Es,It,Nl)', '2006', 'Educational', 'Gameloft', '1', 'Brain Training', 'Comprehensive mental workout across five categories.', 'Complete daily "Stress Tests" and logic challenges.', 'All-in-one personal brain coach.', 'Brain Challenge offers a holistic approach to brain training. Beyond logic and math, it includes "Visual" and "Stress" categories, tracking your daily performance and providing a personal trainer to help you improve.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brain-challenge-usa-enfres', 'NDS', 'Brain Challenge (USA) (En,Fr,Es)', '2006', 'Educational', 'Gameloft', '1', 'Brain Training', 'Comprehensive mental workout across five categories.', 'Complete daily "Stress Tests" and logic challenges.', 'All-in-one personal brain coach.', 'Brain Challenge offers a holistic approach to brain training. Beyond logic and math, it includes "Visual" and "Stress" categories, tracking your daily performance and providing a personal trainer to help you improve.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brain-quest---grades-3-&-4-usa', 'NDS', 'Brain Quest - Grades 3 & 4 (USA)', '2008', 'Educational', 'Electronic Arts', '1', 'Educational Quiz', 'Educational trivia and curriculum-based quizzes.', 'Answer school-grade questions to advance your knowledge.', 'Interactive school-subject trainer.', 'Brain Quest for NDS turns the popular educational cards into a game. Students can test themselves on English, Math, and Science in a fun, reward-based system that makes studying feel like an adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brain-quest---grades-5-&-6-usa', 'NDS', 'Brain Quest - Grades 5 & 6 (USA)', '2008', 'Educational', 'Electronic Arts', '1', 'Educational Quiz', 'Educational trivia and curriculum-based quizzes.', 'Answer school-grade questions to advance your knowledge.', 'Interactive school-subject trainer.', 'Brain Quest for NDS turns the popular educational cards into a game. Students can test themselves on English, Math, and Science in a fun, reward-based system that makes studying feel like an adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brain-voyage-usa-enfres', 'NDS', 'Brain Voyage (USA) (En,Fr,Es)', '2007', 'Puzzle', 'Koei', '1', 'Exploration Puzzle', 'Travel-themed puzzle adventure with worldwide locations.', 'Solve logic puzzles while "traveling" to famous global cities.', 'World-traveling brain teaser.', 'Brain Voyage combines puzzle-solving with a travel narrative. Solve localized puzzles in cities like London and Paris to unlock souvenirs and discover new destinations in this relaxing mental journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz---4-real-europe-enfr', 'NDS', 'Bratz - 4 Real (Europe) (En,Fr)', '2007', 'Adventure', 'AWE Games', '1', 'Fashion Adventure', 'Social simulation and fashion adventure.', 'Go on a mission to stop a movie being made about your life.', 'Fashion and social-based adventure.', 'Join the Bratz girls in 4 Real. Explore the mall, design trendy outfits, and interact with friends in a quest to stay true to yourself. Features various fashion-forward mini-games and customization.');
