INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz---forever-diamondz-europe', 'NDS', 'Bratz - Forever Diamondz (Europe)', '2006', 'Simulation / Adventure', 'Altron', '1', 'Casual', 'Fashion simulation and rhythm-based competitions.', 'Travel across the country to find the best fashion designer.', 'Fashion road trip and talent show.', 'In Bratz: Forever Diamondz, join the girls on a cross-country search for the next big thing in fashion. Compete in figure skating and music shows while designing the sparkliest diamond-themed outfits on your NDS.');
