INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz---super-babyz-europe-dees', 'NDS', 'Bratz - Super Babyz (Europe) (De,Es)', '2007', 'Adventure / Simulation', 'Altron', '1', 'Casual', 'Action-adventure with super-powered baby characters.', 'Defeat an alien invasion using your unique baby superpowers.', 'Super-heroic baby action adventure.', 'Bratz: Super Babyz brings a comic-book twist to the series. Choose your favorite baby and use powers like super speed or strength to fight off an alien threat and save the day in this fun, colorful NDS title.');
