INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz-kidz---party-europe-enfrdeesitsvnoda', 'NDS', 'Bratz Kidz - Party (Europe) (En,Fr,De,Es,It,Sv,No,Da)', '2007', 'Party / Mini-Games', 'Altron', '1-4', 'Party', 'Mini-game collection and social simulation.', 'Win various challenges and host the best neighborhood party.', 'Festive mini-game fun with the Bratz Kidz.', 'Bratz Kidz: Party features a variety of touch-screen games designed for younger players. Customize your room, compete in friendly competitions, and socialise with the Bratz Kidz in a vibrant party setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz-kidz---slumber-party-usa-enfres', 'NDS', 'Bratz Kidz - Slumber Party (USA) (En,Fr,Es)', '2008', 'Party / Mini-Games', 'Altron', '1-4', 'Party', 'Mini-game collection and interior design.', 'Host the ultimate sleepover and complete fun mini-games.', 'Sleepover-themed activities and games.', 'Bratz Kidz: Slumber Party focuses on the fun of staying up late with friends. Decorate the perfect bedroom and master variety-style mini-games like pillow fights and makeover challenges on your NDS.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz-ponyz-europe-enfrdeesitda', 'NDS', 'Bratz Ponyz (Europe) (En,Fr,De,Es,It,Da)', '2006', 'Simulation / Adventure', 'Altron', '1', 'Casual', 'Beauty salon and pet care simulation for ponies.', 'Groom, style, and compete with your magical ponies.', 'Pony grooming and fashion simulation.', 'Step into the world of Bratz Ponyz. Use the touch screen to brush, decorate, and enter your magical ponies into prestigious beauty pageants, unlocking new accessories and fashions as you go.');
