INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz-ponyz-2-europe-enfrdeesitnlsvnoda', 'NDS', 'Bratz Ponyz 2 (Europe) (En,Fr,De,Es,It,Nl,Sv,No,Da)', '2008', 'Simulation / Adventure', 'Altron', '1', 'Casual', 'Enhanced pony styling and more creative mini-games.', 'Win the Year of the Pony competition through style and grace.', 'Creative magical pony sequel.', 'Bratz Ponyz 2 expands the series with more customization options and all-new mini-games. Nurture your pony''s talents in hobbies like music and art while preparing for the grandest fashion show in the forest.');
