INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brave-usa-enfres', 'NDS', 'Brave (USA) (En,Fr,Es)', '2012', 'Action / Adventure', 'Behaviour Interactive', '1', 'Player vs Environment', '3D action-adventure with archery and puzzle solving.', 'Restore the kingdom and save Merida''s mother from a curse.', 'Heroic archery adventure based on the movie.', 'Disney/Pixar''s Brave for NDS lets you play as Merida. Use your bow and sword to battle mystical enemies and solve environmental puzzles in the Scottish Highlands in this faithful movie adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('brave-story---boku-no-kioku-to-negai-japan', 'NDS', 'Brave Story - Boku no Kioku to Negai (Japan)', '2006', 'RPG', 'Marvelous Interactive', '1', 'Turn-based', 'Turn-based RPG with exploration and story-driven combat.', 'Explore a fantasy world to save a friend and find your destiny.', 'Classic fantasy RPG based on the novel.', 'Brave Story: Boku no Kioku to Negai is a deep NDS RPG. Follow Wataru''s journey as he enters a magical realm, meeting new allies and mastering tactical combat to change his fate and return home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bravissi-mots-france-ndsi-enhanced', 'NDS', 'Bravissi-Mots (France) (NDSi Enhanced)', '2009', 'Educational', 'Mindscape', '1', 'Word Puzzle', 'Word puzzles and vocabulary challenges.', 'Solve crossword-style puzzles and expand your French vocabulary.', 'Sophisticated French word puzzle game.', 'Bravissi-Mots is an engaging linguistic trainer for NDS. Challenge your brain with a variety of word-based games and puzzles designed to test your knowledge of the French language in a fun, interactive way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('break-em-all-usa', 'NDS', 'Break ''em All (USA)', '2005', 'Puzzle / Action', 'Midas Interactive', '1', 'Arcade', 'Arcade-style brick-breaking action.', 'Clear all blocks in each level using a paddle and ball.', 'Fast-paced classic brick breaking.', 'Break ''em All offers hundreds of levels of intense arcade action. With multiple power-ups, varied block types, and challenging boss battles, it''s the ultimate handheld experience for fans of the Arkanoid genre.');